 realtime:{beginner:["Introduction to Real-Time Management","Understanding the Intraday Plan","Reading Queue and Service Indicators"],intermediate:["Staffing Variance and Availability","Real-Time Adherence Management","Intraday Reforecasting and Recovery"],professional:["Intraday Command and Recovery Plans","Incident and Escalation Management","Enterprise Real-Time Governance"]},
 scheduling:{beginner:["Scheduling Fundamentals","Shifts, Breaks, and Activities","Reading a Coverage Chart"],intermediate:["Shift and Break Optimization","Schedule Rules and Constraints","Offline Activity Placement"],professional:["Multi-Skill Optimization","Schedule Efficiency and Fairness","Strategic Schedule Design"]},
 forecasting:{beginner:["Volume, AHT, and Workload","Historical Data Preparation and Validation","Forecasting Fundamentals"],intermediate:["Trends, Seasonality, Events, and Anomalies","Interval Forecasting","Forecast Accuracy and Bias"],professional:["Advanced Multi-Channel Forecasting","Forecast Communication and Review","Forecast Governance and Scenarios"]},
 capacity:{beginner:["Workload and Productive Capacity","FTE and Shrinkage Basics","Understanding Staffing Gaps"],intermediate:["Weekly and Monthly Capacity Planning","Workforce Supply Projection","Hiring, Training, and Ramp Planning"],professional:["Long-Range Capacity Strategy","Financial Workforce Scenarios","Capacity Governance"]},
 analytics:{beginner:["Essential WFM Metrics","Understanding Variance","Metric Definitions and Data Quality"],intermediate:["Forecast, Staffing, and Schedule Analysis","Building a WFM Dashboard","WFM Root-Cause Analysis"],professional:["Executive WFM Storytelling","Performance Governance","Benefits and Action Tracking"]},
 engagement:{beginner:["The Employee Schedule Experience","Time-Off, Availability, and Preferences","Workforce Self-Service Fundamentals"],intermediate:["Shift Swaps and Self-Service","Schedule Preferences and Bidding","Fairness and Communication"],professional:["Strategic Workforce Flexibility","Engagement Program Governance","Employee Experience Measurement"]}
