const orientations = {
 realtime:{title:"Understanding Real-Time Management",role:"Real-Time Analyst",definition:"Real-Time Management is the intraday WFM discipline that monitors live demand, staffing, employee availability, and service performance against the operating plan.",why:"Forecasts and schedules describe what should happen. Real-Time Management identifies what is happening now and coordinates proportionate recovery actions before service, employees, or cost are significantly affected.",fit:"Forecasting estimates demand, Capacity Planning determines workforce needs, Scheduling places employees, and Real-Time Management manages the gap between the plan and actual intraday conditions.",objectives:["Define Real-Time Management","Explain how the intraday plan connects with actual conditions","Describe when a variance requires monitoring, escalation, or recovery"],responsibilities:["Monitor service, queues, adherence, occupancy, and backlog","Compare required, scheduled, available, and actual staffing","Investigate demand, AHT, absence, adherence, and technology exceptions","Recommend and track proportionate recovery actions","Maintain an intraday log and support post-incident learning"],skills:["Queue and staffing knowledge","Calm judgment under pressure","Operational communication","Prioritization and escalation"],input:"Forecasts, schedules, staffing requirements, live queue data, adherence states, and incident information",output:"Validated risk assessments, intraday actions, stakeholder updates, and event logs",stakeholders:"Operations, Scheduling, Forecasting, Capacity Planning, Technology, and site leadership",workflow:["Review the plan and guardrails","Monitor demand, staffing, and service","Validate material variance","Assess impact and options","Coordinate the response","Track recovery and document learning"],outcome:"Interpret intraday conditions, identify staffing and queue risks, recommend recovery actions, and communicate decisions clearly."},
 scheduling:{title:"Understanding WFM Scheduling",role:"WFM Scheduler",definition:"WFM Scheduling converts staffing requirements into workable employee schedules by placing shifts, breaks, lunches, and activities against expected demand while respecting skills, availability, contracts, labor rules, and operating constraints.",why:"The correct total headcount is not enough. Employees must be scheduled at the right times, with the right skills and activities, to protect service, compliance, cost, and employee experience.",fit:"Forecasting estimates demand, Capacity Planning determines workforce supply, Scheduling places that supply across intervals, and Real-Time Management manages same-day variance.",objectives:["Explain the purpose and outputs of scheduling","Describe how requirements become shifts and activities","Recognize the tradeoffs among coverage, compliance, efficiency, and fairness"],responsibilities:["Translate interval requirements into schedule demand","Build and maintain shifts, breaks, meals, meetings, and training","Apply skills, availability, contracts, and labor rules","Measure coverage, efficiency, stability, and schedule quality","Publish changes clearly and maintain schedule records"],skills:["Constraint-based planning","Coverage interpretation","Work-rule knowledge","Detail, fairness, and communication"],input:"Interval staffing requirements, employee skills and availability, work rules, contracts, preferences, and activity demand",output:"Published schedules, coverage views, exception lists, and documented schedule decisions",stakeholders:"Employees, Operations, HR, Forecasting, Capacity Planning, Real-Time Management, and labor relations",workflow:["Confirm requirements and planning horizon","Validate workforce and rules","Design shifts and activities","Evaluate coverage and constraints","Resolve exceptions and approve","Publish, maintain, and learn"],outcome:"Read coverage, build compliant schedules, improve shift and activity placement, and explain scheduling tradeoffs."},
 forecasting:{title:"Understanding WFM Forecasting",role:"WFM Forecaster",definition:"WFM Forecasting estimates future customer demand and the work that demand will create. It provides a shared view of when work is expected, how much may arrive, and which assumptions could change the plan.",why:"Under-forecasting can create long waits, missed targets, overtime, and employee pressure. Over-forecasting can create avoidable labor cost and idle capacity.",fit:"Forecasting provides the demand foundation for Capacity Planning, Scheduling, Real-Time Management, Operations, and Finance.",objectives:["Explain the relationship among volume, handle time, and workload","Describe a reliable forecasting process","Recognize forecast error, bias, risk, and uncertainty"],responsibilities:["Collect, clean, and classify historical demand data","Separate trend, seasonality, events, and anomalies","Build interval, daily, weekly, and long-range forecasts","Measure error and bias using consistent definitions","Document assumptions and communicate scenarios"],skills:["Data validation","Pattern recognition","Forecast methods and judgment","Business communication"],input:"Historical demand, handle time, calendars, campaigns, events, operational changes, and business intelligence",output:"Demand and workload forecasts, assumptions, scenarios, accuracy measures, and risk commentary",stakeholders:"Capacity Planning, Scheduling, Real-Time Management, Operations, Finance, Marketing, and leadership",workflow:["Define scope and granularity","Prepare and classify data","Identify demand patterns","Build the baseline forecast","Apply events and scenarios","Review accuracy and communicate risk"],outcome:"Explain forecast purpose, prepare reliable history, build demand and workload views, evaluate forecast quality, and communicate risk."},
 capacity:{title:"Understanding Capacity Planning",role:"Capacity Planner",definition:"Capacity Planning compares future workforce demand with expected workforce supply across weeks, months, or years, then identifies actions needed to close projected gaps.",why:"Hiring, training, nesting, transfers, outsourcing, and budget changes require lead time. Capacity Planning helps the organization act before shortages or surpluses become expensive problems.",fit:"Forecasting provides demand. Capacity Planning converts demand into workforce requirements and supply plans. Scheduling and Real-Time Management execute those plans at shorter horizons.",objectives:["Explain capacity demand and workforce supply","Calculate productive capacity and staffing gaps","Describe the timing and impact of workforce actions"],responsibilities:["Convert workload into productive FTE requirements","Model shrinkage, attrition, hiring, training, and ramp","Project workforce supply by skill, site, and period","Build base, upside, downside, and sensitivity scenarios","Recommend timely actions with cost and service impacts"],skills:["Workload and FTE mathematics","Scenario modeling","Financial awareness","Dependency and risk communication"],input:"Demand forecasts, productivity, shrinkage, workforce rosters, attrition, hiring plans, training capacity, and financial constraints",output:"Capacity demand and supply projections, gap analysis, hiring plans, scenarios, and decision calendars",stakeholders:"Forecasting, Finance, Talent Acquisition, Training, Operations, Scheduling, HR, and leadership",workflow:["Confirm demand and service assumptions","Convert workload into required capacity","Project workforce supply","Identify gaps and timing","Compare workforce scenarios","Agree actions and refresh the plan"],outcome:"Calculate capacity demand and supply, identify future gaps, build hiring and ramp plans, and compare scenarios."},
 analytics:{title:"Understanding WFM Analytics",role:"WFM Analyst",definition:"WFM Analytics turns demand, workforce, schedule, adherence, service, and cost data into trusted information that helps leaders make better decisions.",why:"Metrics alone do not explain performance. Analytics connects results with operational drivers, business impact, and recommended actions.",fit:"Analytics supports every WFM discipline by measuring forecast quality, capacity risk, schedule effectiveness, intraday performance, employee outcomes, and improvement impact.",objectives:["Define essential WFM measures and dimensions","Distinguish symptoms, drivers, and root causes","Communicate findings as clear decisions and actions"],responsibilities:["Define metrics, owners, sources, and calculation rules","Validate completeness, consistency, and materiality","Analyze demand, staffing, schedule, service, and cost variance","Build clear dashboards and recurring performance views","Translate evidence into recommendations and tracked actions"],skills:["Metric design","Data quality and reconciliation","Root-cause analysis","Visualization and stakeholder storytelling"],input:"Forecast, schedule, staffing, adherence, queue, HR, finance, and employee-experience data",output:"Trusted metrics, dashboards, variance analysis, recommendations, and benefit tracking",stakeholders:"All WFM disciplines, Operations, Finance, HR, Technology, and executive leadership",workflow:["Clarify the decision question","Define metrics and grain","Acquire and validate data","Analyze drivers and materiality","Communicate insight and action","Track outcomes and improve"],outcome:"Interpret WFM metrics, diagnose variance, design useful reporting, and communicate evidence-based recommendations."},
 engagement:{title:"Understanding Workforce Engagement",role:"Workforce Engagement Specialist",definition:"Workforce Engagement focuses on how employees access, understand, influence, and manage schedules through transparent processes for availability, preferences, leave, swaps, bidding, overtime, and flexibility.",why:"Well-designed processes improve visibility, trust, participation, and employee experience while protecting coverage, service, labor rules, privacy, and stability.",fit:"Workforce Engagement connects employees with Scheduling, Real-Time Management, Operations, HR, and labor relations through controlled flexibility programs.",objectives:["Explain the employee schedule experience","Describe controlled self-service and flexibility options","Balance employee choice with coverage, fairness, and compliance"],responsibilities:["Design clear availability, preference, leave, and swap processes","Configure eligibility, approval, audit, and coverage rules","Monitor participation, fairness, accessibility, and outcomes","Communicate schedule policies and decision standards","Use feedback and data to improve workforce programs"],skills:["Employee-centered process design","Policy and controls","Change communication","Fairness, accessibility, and measurement"],input:"Employee preferences and availability, schedules, coverage limits, policies, contracts, leave balances, and feedback",output:"Controlled self-service programs, clear policies, participation measures, audit records, and improvement actions",stakeholders:"Employees, Scheduling, Operations, HR, payroll, labor relations, compliance, and Technology",workflow:["Understand employee and business needs","Define policy and guardrails","Design the employee journey","Configure eligibility and controls","Launch and monitor","Measure fairness, adoption, and impact"],outcome:"Evaluate the schedule experience, manage self-service, design fair flexibility programs, and measure employee and operational outcomes."}
};

const levels=[{id:"beginner",label:"Beginner"},{id:"intermediate",label:"Intermediate"},{id:"professional",label:"Professional"}];
const nav=[{id:"overview",label:"Overview",icon:LayoutDashboard},{id:"learn",label:"Learning Paths",icon:GraduationCap},{id:"tools",label:"WFM Tools",icon:Calculator},{id:"resources",label:"Resources",icon:BookOpen}];
const Card=({children,className=""})=><div className={`rounded-3xl border border-slate-200 bg-white p-5 shadow-sm ${className}`}>{children}</div>;
function Logo(){return <div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-gradient-to-br from-[#24213f] to-[#6d5dfc] text-white"><Compass size={21}/></div><div><b>WFM <span className="text-violet-600">Nexus</span></b><div className="text-[8px] font-bold uppercase tracking-[.2em] text-slate-400">Learn · Plan · Lead</div></div></div>}

function Orientation({mod,level,onBegin}){
 const d=orientations[mod.id];
 const levelLabel=levels.find(x=>x.id===level)?.label||level;
 const sections=["Learning objectives","Discipline and role","Business context","Responsibilities and skills","Quick reference","Operating workflow"];
 return <article className="overflow-hidden rounded-3xl border border-[#ded8cc] bg-[#f6f8f8] shadow-sm">
  <header className="border-b border-[#d9d7cf] bg-gradient-to-br from-[#fffaf0] via-[#faf6ec] to-[#edf3f4] px-6 py-9 lg:px-12">
   <div className="mx-auto max-w-5xl">
    <div className="flex flex-wrap items-center justify-between gap-3"><span className="text-[10px] font-black uppercase tracking-[.18em]" style={{color:mod.color}}>◎ {mod.label}</span><div className="flex gap-2"><span className="rounded-full border bg-white px-3 py-1 text-[9px] font-black uppercase text-slate-500">Orientation</span><span className="rounded-full border px-3 py-1 text-[9px] font-black" style={{borderColor:`${mod.color}55`,color:mod.color}}>{levelLabel} Pathway</span></div></div>
    <p className="mt-6 font-serif text-xs font-bold uppercase tracking-[.22em] text-slate-400">Module introduction</p>
    <h2 className="mt-2 font-serif text-4xl font-black text-slate-950 sm:text-5xl">{d.title}</h2>
    <p className="mt-4 max-w-3xl border-l-2 pl-5 font-serif text-base leading-7 text-slate-700" style={{borderColor:mod.color}}>A structured introduction to the discipline, practitioner role, business purpose, operating model, and expected pathway outcome.</p>
    <div className="mt-6 grid overflow-hidden rounded-2xl border bg-white sm:grid-cols-3">{[["Practitioner role",d.role],["Workflow",`${d.workflow.length} stages`],["Pathway",levelLabel]].map(([a,b])=><div key={a} className="border-b p-4 last:border-0 sm:border-b-0 sm:border-r"><div className="text-[9px] font-black uppercase tracking-[.14em] text-slate-400">{a}</div><div className="mt-1 text-sm font-black">{b}</div></div>)}</div>
   </div>
  </header>
  <div className="mx-auto max-w-5xl px-6 py-8 lg:px-12">
   <nav className="rounded-2xl border bg-white p-5"><p className="text-[9px] font-black uppercase tracking-[.16em] text-slate-400">In this orientation</p><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{sections.map((x,i)=><div key={x} className="flex items-center gap-3 text-xs font-semibold"><span className="grid h-6 w-6 place-items-center rounded-full bg-slate-100 text-[10px] font-black">{i+1}</span>{x}</div>)}</div></nav>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">01</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Learning objectives</p><h3 className="mt-1 font-serif text-2xl font-black">What you should understand</h3><p className="mt-3 text-sm text-slate-600">Complete the orientation with a clear mental model before starting lesson one.</p><div className="mt-5 grid gap-3 md:grid-cols-3">{d.objectives.map((x,i)=><div key={x} className="flex gap-3 rounded-xl border bg-white p-4 text-sm leading-6"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-black text-white" style={{background:mod.color}}>{i+1}</span>{x}</div>)}</div></div></div></section>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">02</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Discipline and role</p><h3 className="mt-1 font-serif text-2xl font-black">Definition and practitioner accountabilities</h3><div className="mt-5 grid gap-6 md:grid-cols-2"><div><h4 className="font-serif text-lg font-black">What is {mod.label}?</h4><p className="mt-3 text-sm leading-7 text-slate-700">{d.definition}</p></div><div className="border-t pt-5 md:border-l md:border-t-0 md:pl-6 md:pt-0"><h4 className="font-serif text-lg font-black">The {d.role}</h4><p className="mt-3 text-sm leading-7 text-slate-700">The {d.role} applies this discipline’s methods, validates information, communicates risks, and supports informed workforce decisions.</p></div></div></div></div></section>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">03</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Business context</p><h3 className="mt-1 font-serif text-2xl font-black">Why the discipline matters</h3><h4 className="mt-5 text-sm font-black">Why organizations need it</h4><p className="mt-2 text-sm leading-7 text-slate-700">{d.why}</p><div className="mt-5 rounded-xl border-l-2 bg-white p-5" style={{borderColor:mod.color}}><b className="text-sm">Where it fits in WFM</b><p className="mt-2 text-sm leading-7">{d.fit}</p></div></div></div></section>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">04</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Role profile</p><h3 className="mt-1 font-serif text-2xl font-black">Responsibilities and skills</h3><div className="mt-5 grid gap-5 md:grid-cols-[1.35fr_.85fr]"><div><h4 className="text-sm font-black">Core responsibilities</h4>{d.responsibilities.map(x=><p key={x} className="mt-3 flex gap-3 text-sm leading-6"><CheckCircle2 size={15} className="mt-1 shrink-0" style={{color:mod.color}}/>{x}</p>)}</div><div className="rounded-2xl bg-emerald-50 p-5"><h4 className="text-sm font-black">Skills for success</h4>{d.skills.map(x=><p key={x} className="mt-3 flex gap-3 text-sm"><CheckCircle2 size={15} className="shrink-0 text-emerald-500"/>{x}</p>)}</div></div></div></div></section>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">05</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Quick reference</p><h3 className="mt-1 font-serif text-2xl font-black">Inputs, outputs, and stakeholders</h3><div className="mt-5 overflow-hidden rounded-xl border bg-white">{[["Inputs",d.input,"#1d4ed8"],["Outputs",d.output,"#7c3aed"],["Stakeholders",d.stakeholders,"#047857"]].map(([a,b,c])=><div key={a} className="grid gap-2 border-b p-4 last:border-0 sm:grid-cols-[160px_1fr]"><p className="text-[10px] font-black uppercase" style={{color:c}}>{a}</p><p className="text-sm leading-6">{b}</p></div>)}</div></div></div></section>


   <section className="border-b py-8"><div className="grid grid-cols-[28px_1fr] gap-2"><span className="font-serif text-2xl font-black text-slate-200">06</span><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Operating workflow</p><h3 className="mt-1 font-serif text-2xl font-black">From input to decision</h3><div className="mt-5 space-y-4">{d.workflow.map((x,i)=><div key={x} className="flex items-center gap-4"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-black text-white" style={{background:mod.color}}>{i+1}</span><p className="text-sm font-semibold">{x}</p></div>)}</div></div></div></section>


   <footer className="py-8"><div className="grid gap-5 rounded-2xl border bg-white p-6 md:grid-cols-[1fr_auto] md:items-center"><div><p className="text-[9px] font-black uppercase tracking-[.14em]" style={{color:mod.color}}>Chapter conclusion</p><h3 className="mt-2 font-serif text-2xl font-black">Ready to begin the {levelLabel.toLowerCase()} pathway?</h3><p className="mt-3 text-sm leading-7 text-slate-600">{d.outcome}</p></div><button onClick={onBegin} className="rounded-xl px-5 py-3 text-xs font-black text-white" style={{background:mod.color}}>Begin lesson 1 <ArrowRight size={14} className="inline"/></button></div></footer>
  </div>
 </article>
}
const realtimeLessonDetails={
 "Introduction to Real-Time Management":{
  overview:"Real-Time Management controls the operating day by comparing actual demand, staffing, employee states, and service performance with the intraday plan. The goal is not constant intervention. The goal is early detection, disciplined validation, and proportionate action.",
  terms:[["Intraday plan","The interval-level expectation for demand, workload, staffing, and service."],["Variance","The difference between planned and actual conditions."],["Guardrail","A threshold or rule that defines when monitoring, investigation, or action is required."],["Recovery action","A controlled change intended to reduce operational risk or restore performance."]],
  method:["Review the latest plan, assumptions, thresholds, and known events.","Monitor demand, AHT, staffing, adherence, queues, and backlog together.","Validate whether a variance is real, material, and likely to continue.","Estimate customer, employee, cost, and downstream impact.","Choose the least disruptive action capable of managing the risk.","Record the decision, owner, timing, result, and remaining risk."],
  example:{title:"Late-morning risk",facts:["Required staffing: 42","Available staffing: 38","Volume: 6% above plan","AHT: 4% above plan","Service level: declining for three intervals"],analysis:"The four-person staffing deficit is reinforced by higher demand and AHT. Because the pattern persists across three intervals, passive monitoring is no longer sufficient.",decision:"Validate absence and adherence exceptions, protect scheduled capacity, postpone movable offline work, and review recovery after the next interval."},
  mistakes:["Reacting to one metric without checking related drivers","Taking action before validating data freshness and materiality","Using the most disruptive action first","Failing to record ownership and review time"],
  quiz:[["Which condition best supports intervention?",["A single short-lived metric change","A validated material variance likely to continue","Any difference from plan"],1],["What should follow every recovery action?",["A new forecast only","An immediate escalation","A review time, owner, and documented outcome"],2],["What is the preferred response principle?",["Use the least disruptive effective action","Always cancel offline work","Wait until the daily result is final"],0]],
  takeaways:["RTM manages the gap between plan and actual conditions.","Validation comes before intervention.","Actions should be proportionate, owned, timed, and reviewed."]
 },
 "Understanding the Intraday Plan":{
  overview:"The intraday plan is the operating baseline for each interval. A Real-Time Analyst must distinguish required, scheduled, available, and actual staffing, then connect those staffing views with expected demand, workload, and service outcomes.",
  terms:[["Required staffing","Employees needed to handle expected workload at the agreed service objective."],["Scheduled staffing","Employees planned to work in the interval."],["Available staffing","Scheduled employees expected to be available after known exceptions."],["Actual staffing","Employees actively providing the required work during the interval."]],
  method:["Confirm the interval length, queue scope, skills, and service objective.","Review forecast volume, AHT, workload, and required staffing.","Compare required staffing with scheduled staffing.","Adjust for absence, leave, training, meetings, and known system issues.","Compare available staffing with actual productive staffing.","Flag the earliest material gap and identify its source."],
  example:{title:"Six-interval staffing review",facts:["10:00 required 36, scheduled 38, available 37","10:30 required 39, scheduled 39, available 37","11:00 required 42, scheduled 40, available 37","11:30 required 43, scheduled 40, available 38"],analysis:"Risk begins at 10:30 when available staffing falls two below requirement. The deficit becomes material at 11:00 because demand rises while availability remains flat.",decision:"Treat 10:30 as the prevention point. Confirm recoverable exceptions before 11:00 and protect capacity through the peak."},
  mistakes:["Treating scheduled staffing as guaranteed productive capacity","Ignoring skill mix and queue eligibility","Reviewing daily totals instead of interval timing","Finding the largest gap but missing the earliest decision point"],
  quiz:[["Which staffing view includes known exceptions?",["Required","Available","Scheduled"],1],["Why is the earliest risk interval important?",["It creates more lead time for prevention","It is always the largest gap","It removes the need for validation"],0],["If required is 42 and available is 37, what is the gap?",["5 surplus","5 deficit","79"],1]],
  takeaways:["Each staffing view answers a different question.","Timing and skill mix matter as much as total headcount.","The best intervention point often occurs before service deteriorates."]
 },
 "Reading Queue and Service Indicators":{
  overview:"Queue health cannot be understood from one metric. Service level, ASA, contacts waiting, oldest contact, abandonment, occupancy, and backlog describe different parts of the same operating system and must be interpreted together.",
  terms:[["Service level","The share of contacts answered within a defined threshold."],["ASA","Average time answered contacts waited before connection."],["Occupancy","The share of logged-in time spent handling contacts or after-contact work."],["Backlog","Work received but not yet completed, especially in asynchronous channels."]],
  method:["Check timestamp, interval, queue, and data refresh status.","Compare arrivals and AHT with forecast.","Review staffing and occupancy to understand capacity pressure.","Read queue depth, oldest contact, ASA, and abandonment together.","Decide whether the issue is demand, capacity, productivity, routing, or technology.","Select a response and define the next review point."],
  example:{title:"Rising ASA with stable arrivals",facts:["Volume: on plan","AHT: 9% above plan","Occupancy: 94%","ASA: increased from 35 to 88 seconds","Contacts waiting: rising"],analysis:"Stable arrivals make demand volume an unlikely primary cause. Higher AHT is consuming capacity, high occupancy leaves little recovery room, and queue pressure is accumulating.",decision:"Investigate the AHT increase, protect productive staffing, pause avoidable offline activity, and monitor oldest contact and abandonment."},
  mistakes:["Assuming poor service always means high volume","Treating occupancy as a performance target without context","Using ASA without queue depth or abandonment","Ignoring delayed effects after the original variance ends"],
  quiz:[["High occupancy plus rising ASA usually indicates what?",["Excess capacity","Capacity pressure","Guaranteed high productivity"],1],["Which measure shows the longest current wait?",["Oldest contact","Average handle time","Schedule adherence"],0],["Why inspect AHT when volume is on plan?",["AHT changes workload and capacity consumption","AHT replaces service level","AHT measures absence"],0]],
  takeaways:["Metrics form a connected operating story.","High occupancy can signal limited recovery capacity.","Diagnose the driver before choosing the action."]
 },
 "Staffing Variance and Availability":{
  overview:"Staffing variance analysis explains how a planned workforce becomes actual productive capacity. The analyst builds a bridge from requirement to schedule, availability, and productive staffing, then separates recoverable losses from structural gaps.",
  terms:[["Net staffing variance","Available or actual staffing minus required staffing."],["Availability loss","Scheduled capacity removed by absence, leave, meetings, system issues, or other exceptions."],["Recoverable exception","Capacity that may return through a feasible operational action."],["Structural gap","A deficit that cannot be resolved through normal same-day controls."]],
  method:["Start with required staffing by interval and skill.","Compare the schedule with requirement to identify the planned gap.","Subtract known absence and nonproductive activities.","Reconcile logged-in and correctly skilled actual staffing.","Separate recoverable, movable, and nonrecoverable losses.","Quantify the remaining risk and recommend actions."],
  example:{title:"Staffing variance bridge",facts:["Required: 50","Scheduled: 52","Absence: 4","Training: 3","Incorrect skill assignment: 2","Actual productive: 43"],analysis:"The schedule begins two above requirement, but nine units of capacity are lost. Moving training may recover three, and correcting skill assignment may recover two. Absence remains nonrecoverable today.",decision:"Correct skill assignment first, move training if permitted, then reassess the remaining two-person deficit and service risk."},
  mistakes:["Reporting only the final gap without explaining the bridge","Counting logged-in employees who are not eligible for the work","Treating all shrinkage as recoverable","Moving activities without checking downstream impact"],
  quiz:[["Required is 50 and actual productive staffing is 43. What is the variance?",["7 surplus","7 deficit","93"],1],["Which loss may be recoverable?",["Approved absence already underway","Movable training","Permanent vacancy"],1],["Why build a variance bridge?",["To show where capacity was gained or lost","To replace queue metrics","To calculate forecast bias"],0]],
  takeaways:["Headcount is not the same as productive capacity.","Every gap should be decomposed into explainable drivers.","Recover the least disruptive capacity first."]
 },
 "Real-Time Adherence Management":{
  overview:"Real-time adherence compares scheduled activity with actual employee state. Effective adherence management protects coverage while using accurate data, reasonable grace periods, consistent standards, and proportionate communication.",
  terms:[["Adherence","The degree to which actual activity matches scheduled activity at the scheduled time."],["Conformance","The degree to which total worked time matches the planned duration, regardless of exact timing."],["Exception","A validated reason actual activity differs from the schedule."],["Grace period","An approved tolerance applied before an event is treated as actionable."]],
  method:["Validate schedule, state mapping, timestamp, and system refresh.","Apply approved grace periods and remove known exceptions.","Assess duration, recurrence, queue impact, and employee control.","Prioritize material exceptions rather than every deviation.","Use the approved communication and escalation process.","Document resolution and identify systemic patterns."],
  example:{title:"Five adherence exceptions",facts:["Employee A: 2 minutes late from break","Employee B: 18 minutes in unplanned offline state","Employee C: system state mapping error","Employee D: approved coaching overrun","Employee E: repeated late login during peak"],analysis:"A is within tolerance, C is a data issue, and D has a valid exception. B requires immediate validation because capacity is affected. E requires documented pattern review and operational follow-up.",decision:"Prioritize B, correct C, record D, monitor A, and escalate E through the established process."},
  mistakes:["Treating every deviation as misconduct","Contacting employees before validating system and schedule data","Ignoring duration and service impact","Applying inconsistent standards across teams"],
  quiz:[["Which item should be removed before action?",["Known approved exception","Material unexplained offline time","Repeated peak-period variance"],0],["What is the difference between adherence and conformance?",["Adherence considers timing; conformance emphasizes total duration","They are identical","Conformance measures forecast accuracy"],0],["What should drive prioritization?",["Employee name","Duration, recurrence, control, and impact","Alphabetical order"],1]],
  takeaways:["Validate before contacting or escalating.","Prioritize material and controllable exceptions.","Fairness requires transparent, consistent standards."]
 },
 "Intraday Reforecasting and Recovery":{
  overview:"Intraday reforecasting updates the remaining operating day using actual arrivals, current AHT, backlog, known events, and the latest staffing outlook. The result supports targeted recovery rather than broad reactive action.",
  terms:[["Run rate","The observed pace of demand or workload over a defined period."],["Remaining workload","Expected future work plus carried backlog that still requires capacity."],["Reforecast","An updated estimate based on actual conditions and revised assumptions."],["Recovery window","The remaining time in which an action can materially improve the outcome."]],
  method:["Lock completed intervals and validate actual volume and AHT.","Estimate remaining demand using current patterns and known events.","Add backlog or deferred work that must be recovered.","Recalculate workload and required staffing for remaining intervals.","Compare updated requirement with available staffing.","Select actions by impact, lead time, reversibility, and cost."],
  example:{title:"Afternoon reforecast",facts:["Morning volume: 8% above plan","AHT: 5% above plan","Original remaining volume: 2,400","Expected afternoon uplift: 6%","Available staffing: 44 versus revised need of 49"],analysis:"The revised demand and AHT create a five-person deficit across the afternoon peak. Waiting for final results would remove the recovery window.",decision:"Reforecast remaining intervals, secure targeted overtime or flex capacity, move lower-priority offline work, and publish a timed recovery update."},
  mistakes:["Applying the morning percentage blindly to every remaining interval","Ignoring backlog and channel carryover","Reforecasting demand but not staffing requirement","Using actions whose lead time exceeds the recovery window"],
  quiz:[["What should be locked during a reforecast?",["Completed validated intervals","All original assumptions","Every future interval"],0],["Why include backlog?",["Backlog consumes future capacity","Backlog reduces AHT automatically","Backlog is already completed"],0],["Which action is useful?",["One that can take effect within the recovery window","Any action with the lowest cost","Only permanent hiring"],0]],
  takeaways:["Reforecast the remaining day, not the past.","Demand, AHT, backlog, and staffing must be updated together.","Choose actions that can work within the available time."]
 },
 "Intraday Command and Recovery Plans":{
  overview:"A command and recovery plan converts a material operating risk into a governed response with clear triggers, actions, owners, review points, communications, and exit criteria. The plan should stabilize service without creating unnecessary downstream disruption.",
  terms:[["Trigger","A predefined condition that activates a response or escalation."],["Decision right","Authority assigned to approve or execute an action."],["Exit criterion","The measurable condition that allows recovery actions to stop."],["Recovery playbook","A prepared set of governed response options for known risk types."]],
  method:["Declare the issue, scope, severity, and incident owner.","Confirm evidence and identify the dominant drivers.","Define the target state and recovery horizon.","Sequence actions from least to most disruptive.","Assign owners, approvals, communications, and review times.","Close only after exit criteria and follow-up actions are confirmed."],
  example:{title:"Multi-interval deficit",facts:["Deficit: 12 productive FTE for four intervals","Service level: 18 points below target","Backlog: increasing","Two sites and three skills affected","Technology stable"],analysis:"The broad and persistent gap requires coordinated command rather than isolated queue actions. Capacity recovery must be prioritized by customer impact and skill constraint.",decision:"Activate the recovery playbook, protect critical skills, redeploy eligible capacity, approve targeted overtime, publish 30-minute updates, and define closure criteria."},
  mistakes:["Launching multiple actions without an incident owner","Failing to define when actions should stop","Using broad measures when the risk is skill-specific","Closing the incident when metrics improve for only one interval"],
  quiz:[["What makes a recovery plan governable?",["Clear owners, triggers, timing, and exit criteria","A long list of possible actions","One metric only"],0],["How should actions be sequenced?",["Most disruptive first","Least disruptive effective actions first","Randomly"],1],["When should command close?",["After defined exit criteria are sustained","When the first update is sent","At the end of the day regardless of result"],0]],
  takeaways:["Command requires ownership and decision rights.","Recovery actions need sequence and exit criteria.","Closure includes documentation and learning."]
 },
 "Incident and Escalation Management":{
  overview:"Incident management provides a repeatable way to classify disruption, assemble evidence, assign ownership, escalate decisions, communicate status, and close with learning. Escalation should improve decision speed, not simply increase message volume.",
  terms:[["Severity","A classification based on scope, impact, duration, and recovery complexity."],["Escalation","A transfer of decision, support, or authority to the appropriate level."],["Situation update","A concise statement of facts, impact, actions, decisions, and next update."],["Post-incident review","A structured evaluation of causes, responses, results, and improvements."]],
  method:["Validate the incident and establish the start time.","Classify severity using approved criteria.","Assign an incident owner and functional leads.","State facts, impact, actions, decisions needed, and next update time.","Escalate only to roles able to provide authority or support.","Close with evidence, event chronology, ownership, and lessons."],
  example:{title:"Routing outage",facts:["Voice routing degraded across two queues","Estimated 35% of contacts affected","Oldest contact and abandonment rising","Technology investigating","No confirmed restoration time"],analysis:"The scope, customer impact, and uncertain duration justify formal incident management and technology escalation. WFM must quantify staffing and queue consequences while avoiding unsupported restoration claims.",decision:"Open an incident bridge, classify severity, publish a fact-based update, activate approved continuity actions, and schedule the next update in 20 minutes."},
  mistakes:["Escalating without a clear decision request","Mixing confirmed facts with assumptions","Sending updates without a next update time","Closing without a chronology and action owner"],
  quiz:[["What belongs in a useful escalation?",["Facts, impact, actions, decision needed, next update","Every raw metric available","Unverified restoration times"],0],["Who should receive an escalation?",["Roles able to provide authority or support","Every employee","Only the person who discovered it"],0],["What follows incident closure?",["Post-incident review and tracked actions","Deletion of the event log","No further work"],0]],
  takeaways:["Escalation must request useful authority or support.","Updates separate facts, assumptions, and decisions.","Incident learning is part of closure."]
 },
 "Enterprise Real-Time Governance":{
  overview:"Enterprise RTM governance defines common metrics, thresholds, decision rights, escalation paths, control requirements, and learning routines across sites and regions. Good governance creates comparability and control while preserving justified local flexibility.",
  terms:[["Operating standard","A required enterprise method, definition, or control."],["Decision matrix","A documented allocation of decision authority by issue and severity."],["Control evidence","A record showing that a required review, approval, or action occurred."],["Local variance","An approved departure from the standard for a documented business reason."]],
  method:["Define enterprise outcomes, scope, and minimum controls.","Standardize core metrics, timestamps, thresholds, and severity definitions.","Assign global, regional, site, and functional decision rights.","Define approved playbooks, escalation paths, and evidence requirements.","Measure adoption, consistency, outcome quality, and exceptions.","Review incidents and continuously improve the standard."],
  example:{title:"Three regional control centers",facts:["Different service definitions","Different escalation thresholds","Duplicate executive updates","Inconsistent action logging","Local labor and language requirements"],analysis:"The organization needs common definitions, severity levels, controls, and executive communication while allowing documented local procedures for valid constraints.",decision:"Create an enterprise minimum standard, regional decision matrix, common event log, approved local-variance process, and quarterly control review."},
  mistakes:["Standardizing tools without standardizing definitions","Removing all local discretion","Assigning accountability without decision authority","Measuring compliance but not operational outcomes"],
  quiz:[["What should be standardized first?",["Core definitions, thresholds, roles, and controls","Every local phrase","Office layout"],0],["When is a local variance acceptable?",["When documented, approved, and justified","Whenever a site prefers it","Never"],0],["What should governance measure?",["Adoption, consistency, outcomes, and exceptions","Only meeting attendance","Only service level"],0]],
  takeaways:["Governance creates shared definitions and decision rights.","Local flexibility should be controlled, not eliminated.","Standards improve through evidence and incident learning."]
 }
};


const schedulingLessonDetails={
 "Scheduling Fundamentals":{
  overview:"Scheduling converts interval staffing requirements into workable employee schedules. A sound schedule balances coverage, skills, availability, contracts, work rules, cost, stability, and employee experience.",
  terms:[["Staffing requirement","The number of correctly skilled employees needed in each interval."],["Schedule demand","The requirement profile the scheduler must cover with shifts and activities."],["Coverage variance","Scheduled staffing minus required staffing for an interval."],["Schedule constraint","A rule or condition that limits feasible schedule choices."]],
  method:["Confirm the planning horizon, interval length, queues, and skills.","Validate staffing requirements and operating hours.","Load employee contracts, availability, and work rules.","Build shift patterns that align paid time with demand.","Place breaks, meals, and required activities.","Review coverage, compliance, fairness, and publishability."],
  example:{title:"Building a basic shift plan",facts:["Operating hours: 08:00-18:00","Peak requirement: 24 at 11:00-14:00","Available employees: 28","Shift lengths: 6 or 8 paid hours","Minimum meal window: after 4 hours"],analysis:"A single common start time would overstaff the morning and understaff the afternoon. Staggered 08:00, 09:00, and 10:00 starts align more paid time with the peak while preserving meal compliance.",decision:"Create staggered shift groups, reserve eligible employees for the late requirement, then validate interval coverage after meals and breaks are placed."},
  mistakes:["Scheduling from daily totals instead of interval requirements","Ignoring skill eligibility","Building shifts before validating hard constraints","Optimizing coverage without checking publishability"],
  quiz:[["What is the primary scheduling input?",["Interval staffing requirements","Final service results","Payroll history only"],0],["What does coverage variance compare?",["Forecast and actual volume","Scheduled and required staffing","Adherence and conformance"],1],["Why stagger shift starts?",["To align paid capacity with demand shape","To remove all breaks","To guarantee equal preferences"],0]],
  takeaways:["Scheduling places workforce supply against interval demand.","Feasible schedules satisfy hard rules before preferences.","Coverage must be reviewed after all activities are placed."]
 },
 "Shifts, Breaks, and Activities":{
  overview:"A schedule is more than a shift start and end. Meals, breaks, coaching, meetings, training, and other activities change productive coverage and must be placed within approved windows.",
  terms:[["Shift","The planned span of paid work and activities."],["Break window","The permitted time range for a break placement."],["Offline activity","Paid time assigned away from customer-handling work."],["Activity collision","Overlapping schedule elements that make the schedule invalid or impractical."]],
  method:["Confirm shift duration and legal or contractual windows.","Protect the most constrained meal placements first.","Place breaks to avoid simultaneous capacity loss.","Identify coverage surplus for movable activities.","Check employee sequence and activity collisions.","Recalculate productive interval coverage."],
  example:{title:"Protecting a midday peak",facts:["Peak: 11:30-13:30","Eight employees require meals","Four employees require coaching","Maximum meals at once: two","Coaching is movable within the day"],analysis:"Placing meals and coaching during the peak would remove too much productive capacity. Meals must be staggered within legal windows, while coaching should move to intervals with surplus coverage.",decision:"Limit concurrent meals to two, stagger breaks around the peak, and move coaching to late morning and mid-afternoon surplus intervals."},
  mistakes:["Placing all meals at the same preferred time","Treating paid offline activity as productive coverage","Ignoring legal break windows","Changing activities without communicating affected employees"],
  quiz:[["What should be placed first?",["The most constrained activities","All optional meetings","Employee preferences only"],0],["Why recalculate coverage after activities?",["Activities reduce productive staffing","Activities increase forecast volume","Activities replace work rules"],0],["Which activity is usually easier to move?",["A legally timed meal","Optional coaching","A fixed shift start"],1]],
  takeaways:["Every scheduled activity changes productive coverage.","Constrained activities should be placed before flexible activities.","Staggering protects both compliance and service."]
 },
 "Reading a Coverage Chart":{
  overview:"A coverage chart shows how scheduled productive staffing compares with interval requirements. The scheduler uses the chart to locate the timing, size, duration, and skill impact of surpluses and deficits.",
  terms:[["Undercoverage","Scheduled productive staffing below requirement."],["Overcoverage","Scheduled productive staffing above requirement."],["Coverage efficiency","The degree to which scheduled capacity aligns with required capacity."],["Contiguous variance","A sequence of neighboring intervals with the same coverage problem."]],
  method:["Confirm chart scope, interval, skill, and time zone.","Locate the earliest deficit and largest sustained deficit.","Identify surplus intervals that may support movement.","Check whether the issue comes from shifts, breaks, or activities.","Test feasible start-time or activity changes.","Compare improvement with compliance and stability costs."],
  example:{title:"Interpreting six intervals",facts:["09:00: +4","09:30: +3","10:00: 0","10:30: -3","11:00: -5","11:30: -4"],analysis:"The chart shows early surplus followed by a sustained late-morning deficit. A later start or movement of early offline activity could transfer capacity toward the risk window.",decision:"Shift eligible start times later, review break placement at 10:30-11:30, and avoid using the 09:00 surplus for unnecessary activity until the full-day impact is tested."},
  mistakes:["Focusing only on the single largest deficit","Ignoring the duration of a variance","Moving capacity without checking other skills","Treating all overcoverage as waste"],
  quiz:[["What does -5 mean?",["Five above requirement","Five below requirement","Five percent forecast bias"],1],["Why review contiguous intervals?",["Sustained gaps are harder to absorb","Only daily totals matter","They always show absence"],0],["What should be tested before publishing a change?",["Full-day coverage and constraints","Only the affected interval","Only employee seniority"],0]],
  takeaways:["Read timing, magnitude, duration, and skill together.","The earliest deficit may be the best prevention point.","Schedule changes must improve the whole plan, not one interval only."]
 },
 "Shift and Break Optimization":{
  overview:"Shift and break optimization improves interval alignment by adjusting start times, lengths, break placement, and meal placement without violating hard rules or creating excessive schedule disruption.",
  terms:[["Optimization objective","The measurable result the schedule is designed to improve."],["Hard constraint","A requirement that cannot be violated."],["Soft constraint","A preference or target that may be traded off."],["Marginal improvement","The additional benefit created by one schedule change."]],
  method:["Define the objective and protected constraints.","Establish the baseline coverage result.","Identify the most influential shifts and activities.","Test start-time, length, and break alternatives.","Measure coverage gain and disruption cost.","Select the smallest set of sustainable changes."],
  example:{title:"Optimizing six shifts",facts:["Deficit: four employees at 12:00-13:00","Surplus: five at 08:00-09:00","Six shifts currently start at 08:00","Two may start at 10:00","Break windows allow 30-minute movement"],analysis:"Moving two eligible starts later recovers two units during the peak. Moving two breaks outside the peak can recover the remaining two without changing total paid hours.",decision:"Delay two eligible shifts and move two break placements, then recheck employee constraints and afternoon coverage."},
  mistakes:["Optimizing one metric without guarding compliance","Changing too many schedules for a small gain","Treating soft preferences as hard rules","Ignoring schedule stability"],
  quiz:[["What is optimized first?",["A defined objective under protected constraints","Every employee preference equally","The longest shift"],0],["What is a hard constraint?",["A rule that cannot be violated","A desirable preference","A chart color"],0],["What is the best change set?",["The largest number of changes","The smallest sustainable set that achieves the objective","Only break changes"],1]],
  takeaways:["Optimization needs a clear objective and constraints.","Coverage gains should be weighed against disruption.","Small targeted changes are often more sustainable."]
 },
 "Schedule Rules and Constraints":{
  overview:"Scheduling rules define what is legally, contractually, operationally, and technically feasible. The scheduler distinguishes mandatory constraints from preferences and resolves conflicts transparently.",
  terms:[["Hard rule","A legal, contractual, or operational requirement that must be satisfied."],["Soft preference","A desired condition that may be traded off."],["Infeasibility","A condition where no schedule can satisfy all active hard constraints."],["Constraint priority","The approved order used to resolve competing requirements."]],
  method:["Inventory all rules and identify owners.","Classify each item as hard, soft, or informational.","Validate effective dates, populations, and exceptions.","Test schedule feasibility.","Identify the minimum conflicting constraint set.","Resolve through approved exception or requirement change."],
  example:{title:"Resolving an infeasible schedule",facts:["Minimum rest: 11 hours","Required opening coverage: 10","Only eight employees are opening-eligible","Two employees end late the prior day","No overtime permitted"],analysis:"The opening requirement cannot be met with the eligible workforce and rest rule. The schedule is infeasible, not merely inefficient.",decision:"Escalate the two-person structural gap, evaluate approved alternatives such as changed prior-day endings or qualified flex coverage, and do not violate minimum rest."},
  mistakes:["Treating every preference as mandatory","Overriding rules without authority","Hiding infeasibility with overoptimistic assumptions","Failing to document exceptions"],
  quiz:[["What does infeasible mean?",["The schedule is expensive","No solution satisfies all hard constraints","A preference was missed"],1],["What should never be quietly overridden?",["A hard rule","A chart label","A soft preference"],0],["What should follow an approved exception?",["Documentation and audit evidence","Deletion of the rule","No communication"],0]],
  takeaways:["Classify rules before resolving conflicts.","Infeasibility is a planning finding that requires a decision.","Exceptions require authority and evidence."]
 },
 "Offline Activity Placement":{
  overview:"Offline activities must be scheduled where the operating plan can absorb the temporary capacity loss. Placement decisions use coverage surplus, activity urgency, employee eligibility, and recovery options.",
  terms:[["Activity demand","The number of employees and duration required for an offline activity."],["Placement window","The period in which an activity may occur."],["Coverage floor","The minimum productive staffing protected during placement."],["Batch size","The number of employees assigned to the activity at one time."]],
  method:["Confirm activity purpose, deadline, duration, and eligible population.","Calculate productive capacity removed by each batch.","Identify intervals above the coverage floor.","Sequence urgent and constrained activities first.","Test downstream break and skill interactions.","Publish ownership and contingency rules."],
  example:{title:"Placing four activities",facts:["Two training sessions: 90 minutes each","One meeting: 30 minutes","One coaching block: 60 minutes","Tuesday morning has +6 coverage","Wednesday peak has -4 coverage"],analysis:"Tuesday morning can absorb limited batches, while Wednesday peak cannot. Splitting training into smaller groups protects the coverage floor.",decision:"Place the meeting and one small training batch Tuesday morning, schedule remaining batches in later surplus periods, and keep Wednesday peak protected."},
  mistakes:["Placing activity by calendar availability alone","Ignoring skill-specific coverage","Using the entire surplus with no buffer","Failing to define cancellation triggers"],
  quiz:[["What protects service during activity placement?",["Coverage floor","Activity title","Daily volume total"],0],["Why split batches?",["To reduce interval capacity loss","To increase AHT","To remove eligibility rules"],0],["Where should urgent constrained activity go?",["The earliest feasible protected window","Any employee-preferred time","The largest deficit"],0]],
  takeaways:["Offline activity consumes productive capacity.","Batch size and timing control risk.","Every placement needs a contingency rule."]
 },
 "Multi-Skill Optimization":{
  overview:"Multi-skill optimization allocates employees across queues while protecting scarce specialist skills and using shared capability where the total network benefits most.",
  terms:[["Skill matrix","A record of employee eligibility and proficiency by work type."],["Scarce skill","A capability with limited qualified capacity relative to demand."],["Shared pool","Employees eligible for more than one work type."],["Skill dilution","Loss of specialist coverage caused by assigning scarce capability to lower-priority work."]],
  method:["Validate queue demand and skill requirements.","Map exclusive and shared employee capability.","Protect scarce-skill minimums.","Allocate flexible capacity to the highest marginal need.","Test routing and proficiency effects.","Monitor whether the allocation creates downstream risk."],
  example:{title:"Allocating three queues",facts:["Queue A requires 12 specialists","Queue B requires 10 generalists","Queue C requires 6 bilingual employees","Four employees are A/B skilled","Three are B/C skilled"],analysis:"A and C contain scarce skills. Moving all shared employees into B would improve general coverage but expose specialist queues.",decision:"Protect A and C minimums first, then allocate remaining shared capacity to B according to interval demand and routing behavior."},
  mistakes:["Counting every skill as equally productive","Moving scarce specialists to general work too early","Ignoring routing priority","Optimizing headcount instead of effective capacity"],
  quiz:[["What should be protected first?",["Scarce-skill minimums","The largest team","The simplest queue"],0],["What does a skill matrix show?",["Eligibility and proficiency","Only shift start times","Only forecast volume"],0],["Why monitor after allocation?",["Routing and demand may shift risk","The schedule cannot change","Shared skills remove all uncertainty"],0]],
  takeaways:["Effective capacity depends on skill and proficiency.","Protect scarce skills before allocating flexible capacity.","Optimization must reflect routing behavior."]
 },
 "Schedule Efficiency and Fairness":{
  overview:"A sustainable schedule balances operational efficiency with procedural fairness, schedule stability, access to preferences, and equitable distribution of desirable and undesirable assignments.",
  terms:[["Schedule efficiency","How closely productive scheduled capacity aligns with requirements."],["Procedural fairness","Consistent application of transparent rules and decision processes."],["Outcome equity","Evaluation of how schedule advantages and burdens are distributed."],["Schedule stability","The degree to which published schedules remain predictable."]],
  method:["Define efficiency and fairness measures.","Segment outcomes by relevant schedule groups.","Review preference fulfillment and burden distribution.","Identify whether differences come from rules, demand, or process.","Compare alternative schedules using the same measures.","Document tradeoffs and appeal mechanisms."],
  example:{title:"Comparing two schedule options",facts:["Option A: 94% coverage efficiency, 62% preference fulfillment","Option B: 91% coverage efficiency, 81% preference fulfillment","Option A assigns 70% of late shifts to one group","Option B distributes late shifts more evenly"],analysis:"Option A has a small efficiency advantage but concentrates undesirable work and fulfills fewer preferences. The operational benefit may not justify the fairness and stability cost.",decision:"Select or refine Option B unless the three-point efficiency gap creates material service risk, and document the decision standard."},
  mistakes:["Equating fairness with identical outcomes","Using efficiency as the only objective","Ignoring who receives undesirable assignments","Changing rules without transparent communication"],
  quiz:[["What is procedural fairness?",["Consistent transparent decision rules","Identical schedules for everyone","Maximum efficiency"],0],["What should be compared across options?",["Both operational and employee outcomes","Only preference fulfillment","Only paid hours"],0],["Why segment outcomes?",["To detect concentrated burden or access differences","To remove work rules","To increase forecast volume"],0]],
  takeaways:["Fairness concerns both process and outcomes.","Small efficiency gains may create large experience costs.","Transparent measures support defensible decisions."]
 },
 "Strategic Schedule Design":{
  overview:"Strategic schedule design creates a portfolio of shift patterns and flexibility mechanisms that fits long-term demand, workforce supply, operating hours, employee needs, and business strategy.",
  terms:[["Schedule portfolio","The mix of full-time, part-time, fixed, rotating, and flexible patterns."],["Demand fit","How well the portfolio aligns with recurring demand shape."],["Flex mechanism","A controlled way to adjust capacity, such as flex hours or voluntary extensions."],["Design scenario","A coherent future operating option tested against common assumptions."]],
  method:["Define future demand shape and operating strategy.","Assess current portfolio fit and limitations.","Design alternative shift and flexibility models.","Model coverage, cost, compliance, attraction, and stability.","Test scenarios under demand and workforce uncertainty.","Select a roadmap with pilots, controls, and success measures."],
  example:{title:"Extending operating hours",facts:["Current hours: 08:00-18:00","Future hours: 07:00-22:00","Demand is low at edges and peaks at 12:00-16:00","Current workforce is mostly fixed eight-hour shifts","Part-time interest exists"],analysis:"Extending all full-time shifts would overstaff low-demand edges and increase cost. A mixed portfolio can cover the wider span with better demand fit.",decision:"Pilot staggered full-time shifts, targeted part-time edge coverage, and controlled voluntary extensions, then measure coverage, cost, fill rate, and schedule stability."},
  mistakes:["Extending existing patterns without redesign","Ignoring labor-market feasibility","Designing flexibility without controls","Selecting a portfolio from one demand scenario"],
  quiz:[["What is a schedule portfolio?",["A mix of shift and flexibility patterns","One standard shift","A queue dashboard"],0],["Why test scenarios?",["Future demand and supply are uncertain","To eliminate all constraints","To avoid measurement"],0],["What should follow design selection?",["A controlled pilot and success measures","Immediate enterprise rollout","Removal of employee communication"],0]],
  takeaways:["Strategic design starts with future demand shape.","A mixed portfolio can outperform one standard pattern.","Pilots and controls reduce implementation risk."]
 }
};


const forecastingLessonDetails={
 "Volume, AHT, and Workload":{overview:"Forecasting starts by translating expected contacts and handling time into workload. Volume explains how many interactions are expected, AHT explains average effort, and workload combines both drivers into time required.",terms:[["Volume","Contacts expected in a defined period."],["AHT","Average effort per contact, including approved after-contact work."],["Workload","Total handling effort created by demand."],["Unit conversion","Converting seconds into hours before capacity use."]],method:["Confirm channel, period, and volume definition.","Validate matching AHT scope.","Multiply volume by AHT seconds.","Divide by 3,600 for hours.","Calculate channels separately.","Document assumptions and sensitivities."],example:{title:"Three-channel workload",facts:["Voice: 1,200 at 420 seconds","Chat: 800 at 600 seconds","Email: 500 at 480 seconds"],analysis:"Voice creates 140 hours, chat creates 133.33 raw hours, and email creates 66.67 hours. Chat concurrency must be applied before staffing.",decision:"Maintain channel forecasts separately and publish both demand and workload."},mistakes:["Mixing minutes and seconds","Combining channels too early","Using mismatched AHT","Treating workload as paid hours"],quiz:[["Which two demand drivers are multiplied to calculate raw workload?",["Volume and AHT","Volume and shrinkage","AHT and adherence"],0],["Why is volume multiplied by AHT and then divided by 3,600?",["To convert workload from seconds to hours","To calculate forecast bias","To remove seasonal effects"],0],["When should workload from different channels be combined?",["Before applying channel-specific logic","After completing channel-specific calculations and adjustments","Whenever the channels have equal volume"],1]],takeaways:["Volume and AHT jointly determine workload.","Units must be consistent.","Channel mechanics precede staffing."]},
 "Historical Data Preparation and Validation":{overview:"Reliable forecasts require history that represents true demand. Preparation identifies missing records, duplicates, closures, routing changes, anomalies, and events without erasing valid signals.",terms:[["Completeness","Whether every expected record exists."],["Anomaly","An observation materially different from context."],["Event label","A documented business cause attached to history."],["True demand","Demand without avoidable measurement distortion."]],method:["Define grain and sources.","Test completeness and duplicates.","Reconcile totals.","Identify closures, outages, and events.","Choose retain, replace, exclude, or label.","Document adjustments and preserve raw history."],example:{title:"Auditing four weeks",facts:["One missing interval","Two duplicates","Holiday closure","Routing outage","Valid campaign uplift of 22%"],analysis:"Remove duplicates, label closure and outage, retain the valid campaign, and treat the missing interval through an approved method.",decision:"Create an adjustment log and traceable clean history."},mistakes:["Deleting every outlier","Changing data without audit trail","Treating closures as normal lows","Mixing received and handled demand"],quiz:[["What happens to valid campaign demand?",["Delete","Retain and label","Replace with mean"],1],["Why preserve raw history?",["Traceability","Increase volume","Calculate occupancy"],0],["First quality check?",["Completeness and grain","Staffing","Adherence"],0]],takeaways:["Clean data remains traceable.","Anomalies require explanation.","Definitions must stay consistent."]},
 "Forecasting Fundamentals":{overview:"A baseline forecast estimates expected demand before event and judgment adjustments. The method should fit data quality, horizon, stability, and business context.",terms:[["Baseline forecast","Estimate before future-event adjustments."],["Forecast horizon","Time between creation and predicted period."],["Naive forecast","Simple benchmark from a comparable recent period."],["Assumption","Documented belief used where evidence is incomplete."]],method:["Define purpose, horizon, and grain.","Select comparable history.","Establish a benchmark.","Test baseline methods.","Compare error, bias, stability, and clarity.","Document method and assumptions."],example:{title:"Weekly baseline",facts:["Recent weeks: 9,800; 10,100; 10,000; 10,300","No structural change","No special event","Four-week average: 10,050"],analysis:"The stable series supports a transparent recent average.",decision:"Use 10,050 as baseline and retain 10,300 as a naive benchmark."},mistakes:["Complexity without value","Incomparable history","Hidden judgment","Publishing without assumptions"],quiz:[["What should be established before future event adjustments are applied?",["A baseline forecast should be established.","A final employee schedule should be established.","An adherence report should be established."],0],["Why should a simple benchmark be retained when testing a forecasting method?",["A benchmark helps determine whether the selected method adds measurable value.","A benchmark removes all forecast uncertainty.","A benchmark replaces the historical dataset."],0],["Which factors should influence the selection of a baseline forecasting method?",["Forecast horizon, time grain, data quality, and demand stability should influence method selection.","Employee preference alone should influence method selection.","The color assigned to the queue should influence method selection."],0]],takeaways:["Start transparently.","Complexity must add value.","Publish assumptions."]},
 "Trends, Seasonality, Events, and Anomalies":{overview:"Demand history contains recurring patterns, directional movement, events, and unusual observations. Separating these components prevents double counting.",terms:[["Trend","Persistent directional movement."],["Seasonality","Recurring calendar pattern."],["Event effect","Change linked to a known occurrence."],["Anomaly","Unusual observation not normally repeatable."]],method:["Plot the correct grain.","Identify calendar patterns.","Estimate trend.","Map events and changes.","Investigate anomalies.","Check adjustment overlap."],example:{title:"Classifying annual demand",facts:["Mondays +12%","December +20%","Campaign +15%","Quarterly growth +2%","One outage"],analysis:"Monday and December are seasonal, campaign is an event, growth is trend, and outage is an anomaly.",decision:"Model separately and prevent overlapping effects from being counted twice."},mistakes:["Calling every rise trend","Treating events as seasonality","Using outage handling as true demand","Stacking adjustments blindly"],quiz:[["Which forecasting component describes a pattern that repeats at a consistent calendar position?",["Seasonality describes a recurring calendar pattern.","An anomaly describes an unusual observation that is not normally repeatable.","Forecast bias describes a systematic directional error."],0],["How should persistent quarterly demand growth normally be classified?",["Persistent quarterly demand growth should be classified as a trend.","Persistent quarterly demand growth should be classified as a closure.","Persistent quarterly demand growth should be classified as a routing change."],0],["Why should trend, seasonality, events, and anomalies be analyzed separately?",["They should be analyzed separately to avoid double counting and improve forecast assumptions.","They should be analyzed separately to delete historical demand.","They should be analyzed separately to calculate schedule adherence."],0]],takeaways:["Components need distinct treatment.","Handled work may not equal demand.","Check adjustment overlap."]},
 "Interval Forecasting":{overview:"Interval forecasting distributes daily demand across intraday periods using validated profiles and reconciles interval totals to the approved daily forecast.",terms:[["Intraday profile","Share of daily demand by interval."],["Disaggregation","Distribution into smaller periods."],["Reconciliation","Ensuring intervals equal the daily total."],["Profile drift","Sustained change in intraday shape."]],method:["Validate daily total.","Select comparable profiles.","Confirm shares total 100%.","Multiply total by each share.","Control rounding.","Review peaks and event timing."],example:{title:"Daily disaggregation",facts:["Daily total: 1,000","09:00: 8%","09:30: 10%","10:00: 12%","Remaining: 70%"],analysis:"The first intervals are 80, 100, and 120; remaining intervals total 700.",decision:"Reconcile all rounded intervals to exactly 1,000."},mistakes:["One profile for every day","Profiles not totaling 100%","Uncontrolled rounding","Ignoring event timing"],quiz:[["What must all interval profile shares total before demand is disaggregated?",["The interval profile shares must total 100%.","The interval profile shares must equal the AHT target.","The interval profile shares must equal the shrinkage rate."],0],["How is the forecast volume for an individual interval calculated?",["The daily forecast is multiplied by the interval profile share.","The daily forecast is divided by AHT.","Scheduled staffing is subtracted from actual volume."],0],["Why must rounded interval forecasts be reconciled?",["Rounded interval forecasts must be reconciled to preserve the approved daily forecast total.","Rounded interval forecasts must be reconciled to increase forecast bias.","Rounded interval forecasts must be reconciled to remove demand peaks."],0]],takeaways:["Profiles distribute daily demand.","Comparable days matter.","Rounding requires reconciliation."]},
 "Forecast Accuracy and Bias":{overview:"Forecast evaluation measures error size, direction, and concentration. Accuracy shows closeness, while bias shows whether forecasts are systematically high or low.",terms:[["Forecast error","Actual minus forecast."],["Absolute error","Error magnitude without direction."],["WAPE","Absolute errors divided by actual demand."],["Bias","Net signed error divided by actual demand."]],method:["Align definitions.","Calculate signed and absolute errors.","Aggregate WAPE.","Calculate bias.","Segment error.","Recommend changes for persistent patterns."],example:{title:"Four-week review",facts:["Forecasts: 100, 120, 90, 110","Actuals: 110, 100, 100, 120","Absolute error: 50","Actual total: 430"],analysis:"WAPE is 11.63%. Net error is +10, so bias is +2.33%, slight underforecasting under Actual-minus-Forecast.",decision:"Investigate the concentrated second-period overforecast."},mistakes:["Averaging unstable percentages","Accuracy without bias","Changing method after one period","Mixing sign conventions"],quiz:[["What does WAPE measure in a forecast-accuracy review?",["WAPE measures aggregate absolute forecast-error magnitude relative to actual demand.","WAPE measures schedule fairness across employee groups.","WAPE measures employee occupancy during the forecast period."],0],["What does positive bias indicate when error is defined as Actual minus Forecast?",["Positive bias indicates overall underforecasting.","Positive bias indicates overall overforecasting.","Positive bias indicates that no forecast error exists."],0],["Can low net bias coexist with substantial absolute forecast error?",["Yes, because positive and negative errors can offset one another.","No, because low bias always means high forecast accuracy.","This relationship occurs only in schedule analysis."],0]],takeaways:["Accuracy and bias differ.","Use one sign convention.","Segment before changing methods."]},
 "Advanced Multi-Channel Forecasting":{overview:"Multi-channel forecasting models voice, chat, messaging, and asynchronous work separately before coordinating shared journeys and capacity.",terms:[["Concurrency","Simultaneous interactions per employee."],["Asynchronous backlog","Work available for later completion."],["Channel shift","Demand moving between channels."],["Effective workload","Workload adjusted for channel mechanics."]],method:["Forecast channel arrivals.","Apply channel effort assumptions.","Adjust concurrency.","Model backlog and service windows.","Check channel shift.","Reconcile demand and workload."],example:{title:"Voice, chat, and email",facts:["Voice: 900 x 420 seconds","Chat: 600 x 720 seconds, concurrency 2","Email: 300 x 540 seconds","Backlog: 60 emails"],analysis:"Voice is 105 hours, chat is 60 effective hours, and email is 54 hours including backlog.",decision:"Validate achieved concurrency and shared-skill assumptions before staffing."},mistakes:["Voice logic for every channel","Ignoring backlog","Using theoretical concurrency","Double counting channel shift"],quiz:[["Which channel characteristic reduces simplified effective chat workload?",["Achieved concurrency reduces simplified effective chat workload.","Shrinkage reduces simplified effective chat workload.","Forecast bias reduces simplified effective chat workload."],0],["What should an asynchronous email workload forecast include?",["The forecast should include new arrivals and relevant opening backlog.","The forecast should include answered contacts only.","The forecast should include AHT only."],0],["Why should channels be forecast separately before their workloads are coordinated?",["Channels should be forecast separately because their workload mechanics differ.","Channels should be forecast separately because their volumes are always equal.","Channels should be forecast separately to avoid reconciling total demand."],0]],takeaways:["Channel mechanics matter.","Backlog creates future demand.","Shared staffing requires validation."]},
 "Forecast Communication and Review":{overview:"A forecast review converts models and assumptions into a decision narrative covering baseline, changes, uncertainty, scenarios, risks, and required decisions.",terms:[["Forecast narrative","What changed, why, impact, and decision."],["Confidence range","Plausible uncertainty around the estimate."],["Scenario","Alternative built from explicit assumptions."],["Decision request","Specific approval or action required."]],method:["State scope and version.","Show baseline and changes.","Explain assumptions.","Present scenarios.","Translate workforce impact.","Close with decisions and timing."],example:{title:"Operations and Finance review",facts:["Baseline: 100,000","Base: +4%","Upside: +9%","Downside: -2%","Campaign pending"],analysis:"The campaign is the major uncertainty and changes staffing and cost outcomes.",decision:"Present all scenarios and assign the campaign decision deadline and owner."},mistakes:["False precision","Hidden assumptions","Scenarios without impact","No decision request"],quiz:[["What should a forecast-review meeting conclude with?",["The meeting should conclude with decisions, owners, and the next review date.","The meeting should conclude with only a forecast chart.","The meeting should conclude with unprocessed historical data."],0],["Why should a forecast review include alternative scenarios?",["Alternative scenarios show the operational and financial consequences of uncertain assumptions.","Alternative scenarios remove the need to select a working baseline.","Alternative scenarios are used to calculate schedule adherence."],0],["What should a forecast narrative communicate?",["A forecast narrative should explain what changed, why it changed, the impact, and the decision required.","A forecast narrative should contain only formulas and calculations.","A forecast narrative should explain the schedule-bidding process."],0]],takeaways:["Forecasts support decisions.","Uncertainty should be actionable.","Reviews need owners and dates."]},
 "Forecast Governance and Scenarios":{overview:"Forecast governance establishes ownership, version control, assumptions, approval gates, scenario standards, and learning cadence.",terms:[["Forecast version","Identified forecast state."],["Assumption owner","Accountable source for an input."],["Approval gate","Point requiring authorization."],["Scenario governance","Rules for scenario creation and retirement."]],method:["Define products and owners.","Establish version controls.","Assign assumptions and deadlines.","Standardize scenarios.","Approve and publish.","Review accuracy and process effectiveness."],example:{title:"Monthly governance",facts:["Three emailed files","No campaign owner","Different team versions","Inconsistent scenario names","Irregular accuracy review"],analysis:"Traceability and decision control are the primary risks.",decision:"Create one repository, naming standard, assumption register, approval calendar, and monthly review."},mistakes:["Governance as model approval only","Silent assumption changes","Publishing without version ID","Keeping obsolete scenarios"],quiz:[["Which governance control prevents different teams from using conflicting forecast versions?",["Version and publication control prevents teams from using conflicting forecast versions.","A higher AHT assumption prevents teams from using conflicting forecast versions.","Additional forecast intervals prevent teams from using conflicting forecast versions."],0],["Who should be accountable for a campaign assumption used in the forecast?",["A named business owner should be accountable for the campaign assumption.","No one should be accountable for the campaign assumption.","The employee schedule should be accountable for the campaign assumption."],0],["What should occur after a forecast is published?",["Accuracy, decision, and process reviews should occur after publication.","All forecast assumptions should be deleted after publication.","No further governance activity should occur after publication."],0]],takeaways:["Governance creates traceability.","Assumptions need owners.","Learning continues after publication."]}
};


const capacityLessonDetails={
 "Workload and Productive Capacity":{
  overview:"Capacity planning begins by converting forecast demand into workload and productive workforce requirements. The planner must keep volume, handle time, productive hours, and available productive FTE in consistent units.",
  terms:[["Workload hours","The total handling effort created by forecast demand."],["Productive FTE","Workforce capacity available for productive work after nonproductive time is excluded."],["Productive hours per FTE","Expected productive hours contributed by one FTE in the planning period."],["Capacity variance","Available productive FTE minus required productive FTE."]],
  method:["Confirm the planning period, demand scope, and unit definitions.","Convert forecast volume and AHT into workload hours.","Validate productive hours available per FTE.","Divide workload by productive hours per FTE.","Compare available productive FTE with the requirement.","Document assumptions, risk, action, owner, and review date."],
  example:{title:"Weekly productive-capacity requirement",facts:["Forecast volume: 18,000 contacts","AHT: 480 seconds","Productive hours per FTE: 32 per week","Available productive capacity: 72 FTE"],analysis:"The demand creates 2,400 workload hours and requires 75 productive FTE, leaving a three-FTE deficit.",decision:"Validate assumptions and assign a capacity action for the three-FTE deficit."},
  mistakes:["Treating workload hours as paid hours","Mixing time periods or units","Ignoring channel-specific effort","Comparing productive demand with gross headcount"],
  quiz:[["What does productive capacity represent?",["The workload an available workforce can complete in a defined period.","The total paid headcount regardless of availability.","The forecast-error percentage for the period."],0],["How is required productive FTE calculated?",["Divide workload hours by productive hours per FTE.","Multiply workload hours by shrinkage.","Subtract AHT from forecast volume."],0],["What does a negative capacity variance indicate?",["Available productive capacity is below the requirement.","Available productive capacity exceeds the requirement.","Forecast volume and AHT are equal."],0]],
  takeaways:["Workload and capacity must use the same period and units.","Productive FTE differs from gross headcount.","Quantify capacity gaps before selecting actions."]
 },
 "FTE and Shrinkage Basics":{
  overview:"FTE and shrinkage calculations translate productive workforce demand into the paid capacity required. The planner must distinguish headcount, paid FTE, productive FTE, and gross FTE.",
  terms:[["Headcount","The number of individual employees, regardless of contracted hours."],["Paid FTE","Paid hours expressed as a full-time-equivalent measure."],["Productive FTE","FTE capacity available for demand-handling work after shrinkage."],["Shrinkage","Paid time unavailable for demand handling because of planned or unplanned activities."]],
  method:["Define the full-time paid-hours standard.","Confirm the productive FTE requirement.","Validate the shrinkage rate and included categories.","Gross up productive FTE for shrinkage.","Convert gross FTE into headcount using the contract mix.","Test sensitivity to alternative shrinkage assumptions."],
  example:{title:"Comparing shrinkage assumptions",facts:["Productive FTE required: 80","Low shrinkage: 20%","Base shrinkage: 25%","High shrinkage: 30%"],analysis:"At 20% shrinkage, the requirement is 100.00 gross FTE. At 25%, it is 106.67 gross FTE. At 30%, it is 114.29 gross FTE.",decision:"Use 106.67 gross FTE for the approved 25% base case and retain the 20% and 30% results as sensitivity boundaries."},
  mistakes:["Subtracting shrinkage directly from productive FTE","Using headcount and FTE interchangeably","Applying an outdated shrinkage assumption","Failing to define included shrinkage categories"],
  quiz:[["What does productive FTE measure?",["Capacity available for demand-handling work.","Every person on the employee roster.","Overtime hours only."],0],["How is gross FTE calculated from productive FTE?",["Divide productive FTE by one minus the shrinkage rate.","Multiply productive FTE by the shrinkage rate.","Subtract the shrinkage rate from headcount."],0],["What happens when shrinkage increases and productive demand is unchanged?",["Gross FTE increases.","Gross FTE decreases automatically.","Gross FTE remains unchanged."],0]],
  takeaways:["Headcount, paid FTE, productive FTE, and gross FTE answer different questions.","Gross FTE must account for shrinkage.","Sensitivity testing shows how shrinkage assumptions affect workforce demand."]
 },
 "Understanding Staffing Gaps":{
  overview:"A staffing gap compares required capacity with available capacity by period, skill, site, or channel. Effective analysis identifies the size, timing, duration, and last practical decision date for each material gap.",
  terms:[["Staffing gap","Available productive FTE minus required productive FTE."],["Deficit","A negative staffing gap where available capacity is below requirement."],["Surplus","A positive staffing gap where available capacity exceeds requirement."],["Decision point","The latest practical date for approving an action before its lead time expires."]],
  method:["Align demand and supply to the same period, skill, site, and FTE definition.","Calculate required and available productive FTE.","Compute the signed staffing gap for each period.","Identify the first deficit, largest deficit, and duration of risk.","Map feasible workforce actions and their lead times.","Backsolve the decision point and document the owner, action, timing, and residual risk."],
  example:{title:"Three-month staffing-gap review",facts:["January requirement: 120 productive FTE; available: 124","February requirement: 126 productive FTE; available: 123","March requirement: 132 productive FTE; available: 124","External recruitment lead time: eight weeks"],analysis:"January has a four-FTE surplus, February has a three-FTE deficit, and March has an eight-FTE deficit. February requires a bridge action, while March requires a recruitment decision before the lead-time window closes.",decision:"Use the January surplus only where timing and skill permit, create a February bridge action, and approve March recruitment at least eight weeks before productive capacity is required."},
  mistakes:["Reporting only the largest gap and missing the first risk period","Mixing gross FTE, productive FTE, and headcount","Offsetting a skill-specific deficit with an unusable surplus","Identifying a future gap without calculating the decision deadline"],
  quiz:[["How is the signed staffing gap calculated?",["Subtract required productive FTE from available productive FTE.","Add required and available productive FTE.","Divide forecast volume by AHT."],0],["What does a negative staffing gap indicate?",["Available productive capacity is below requirement.","Available productive capacity exceeds requirement.","Forecast and actual demand are equal."],0],["Why should the planner calculate a decision point?",["The decision point preserves enough lead time to implement the selected action.","The decision point eliminates uncertainty.","The decision point replaces staffing-gap calculation."],0]],
  takeaways:["Staffing gaps require a consistent sign convention and FTE definition.","Gap timing, duration, skill, and lead time matter as much as magnitude.","Every material gap needs an owner and decision deadline."]
 },
 "Weekly and Monthly Capacity Planning":{
  overview:"Weekly and monthly capacity planning translates an approved monthly workforce requirement into time-phased weekly demand and supply. The planner must preserve monthly reconciliation while identifying short-duration risks that a monthly average can hide.",
  terms:[["FTE-week","One full-time equivalent of productive capacity available for one week."],["Weekly requirement share","The proportion of the monthly capacity requirement assigned to a specific week."],["Temporary capacity loss","A time-limited reduction in available productive FTE, such as training or leave."],["Monthly reconciliation","The control that confirms weekly requirements sum to the approved monthly plan."]],
  method:["Confirm the approved monthly productive FTE requirement and weekly demand profile.","Allocate the monthly requirement across weeks using validated requirement shares.","Project available productive FTE for each week.","Apply time-specific losses such as training, leave, or transfers.","Calculate the signed weekly capacity gap and identify the earliest decision point.","Reconcile weekly requirements to the monthly total and assign actions, owners, and review dates."],
  example:{title:"Four-week capacity reconciliation",facts:["Approved monthly requirement: 400 FTE-weeks","Weekly requirement shares: 23%, 24%, 26%, and 27%","Available productive supply: 94, 96, 99, and 102 FTE","Training removes five productive FTE in Week 3"],analysis:"Weekly requirements are 92, 96, 104, and 108 productive FTE. After the Week 3 training reduction, the weekly gaps are +2, 0, -10, and -6 productive FTE. The monthly total remains balanced at 400 FTE-weeks, but the weekly view reveals concentrated risk.",decision:"Protect Week 3 through a feasible activity move or temporary capacity action, assign a Week 4 mitigation, and refresh demand and supply assumptions in the next planning cycle."},
  mistakes:["Using a monthly average that hides weekly deficits","Failing to reconcile weekly allocations to the approved monthly total","Applying temporary capacity losses to the wrong week","Moving activity without checking whether risk is transferred to another period"],
  quiz:[["Why should a monthly capacity plan be reviewed by week?",["Weekly review reveals time-specific surpluses and deficits hidden by the monthly average.","Weekly review removes the need for monthly reconciliation.","Weekly review guarantees that demand will remain stable."],0],["What must weekly productive FTE requirements reconcile to?",["They must reconcile to the approved monthly capacity requirement.","They must reconcile to employee preference totals.","They must reconcile to the previous year's headcount."],0],["How should a temporary training loss be reflected?",["The productive FTE loss should be applied to the week in which training occurs.","The loss should be spread equally across every month.","The loss should be excluded from the supply plan."],0]],
  takeaways:["Weekly detail exposes timing risks hidden by monthly averages.","Weekly requirements must reconcile to the approved monthly plan.","Temporary capacity losses require time-specific actions and ownership."]
 },
 "Workforce Supply Projection":{
  overview:"A workforce supply projection shows how opening productive capacity changes through attrition, hiring, training, ramp, transfers, leave, and returns. A transparent waterfall keeps continuing-workforce capacity separate from new-hire contribution.",
  terms:[["Opening supply","Productive FTE available at the start of the planning period."],["Attrition","Workforce capacity expected to leave during the period."],["Ramp profile","The time-phased productive contribution of a new-hire cohort."],["Supply waterfall","A period-by-period bridge from opening supply to ending productive FTE."]],
  method:["Confirm opening productive FTE by skill, site, and period.","Apply attrition to the population covered by the approved assumption.","Add hires only when their training and ramp contribution becomes productive.","Add transfers and returns and subtract outbound movements and leave.","Keep continuing-workforce and new-hire cohort lines separate.","Reconcile ending supply, document assumptions, and compare supply with capacity demand."],
  example:{title:"Four-month supply waterfall",facts:["Opening continuing-workforce productive FTE: 200","Monthly attrition: 2% on the continuing workforce","Twenty new hires start in Month 2","New-hire contribution: 0% in Month 2, 50% in Month 3, and 80% in Month 4","Five productive FTE transfer out in Month 4"],analysis:"Continuing-workforce productive FTE declines to 196.00, 192.08, 188.24, and 184.48. New hires add 10.00 productive FTE in Month 3 and 16.00 in Month 4. After the outbound transfer, Month 4 ending supply is 195.48 productive FTE.",decision:"Publish the continuing-workforce, new-hire, and transfer lines separately, state that new-hire attrition is excluded from this teaching example, and compare each month's ending supply with required productive FTE."},
  mistakes:["Counting hires as fully productive when they start","Applying attrition inconsistently across workforce cohorts","Mixing headcount, gross FTE, and productive FTE","Hiding transfers or ramp assumptions inside one net adjustment"],
  quiz:[["What is the purpose of a workforce supply waterfall?",["It shows how workforce movements change productive FTE from opening to ending supply.","It replaces the demand forecast.","It calculates schedule adherence."],0],["When should new hires enter productive supply?",["New hires should enter productive supply according to their validated training and ramp profile.","New hires should always be counted as fully productive on their first day.","New hires should never be included in a capacity plan."],0],["Why should workforce cohorts be kept separate?",["Separate cohort lines make attrition, ramp, and movement assumptions transparent.","Separate cohort lines eliminate the need for reconciliation.","Separate cohort lines make every employee equally productive."],0]],
  takeaways:["Supply projections bridge opening capacity to ending productive FTE.","New hires contribute according to training and ramp timing.","Cohort-specific assumptions improve transparency and control."]
 },
 "Hiring, Training, and Ramp Planning":{
  overview:"Hiring, training, and ramp planning backsolves workforce actions from the date productive capacity is required. The plan connects recruiting lead time, offer acceptance, training yield, nesting, support constraints, and productivity ramp.",
  terms:[["Required productive date","The date new workforce capacity must be able to perform the work."],["Training yield","The proportion of training starters expected to complete successfully."],["Offer acceptance","The proportion of accepted candidates relative to offers or required acceptances under the stated process."],["Nesting","A supported transition period between training and independent productive work."]],
  method:["Confirm the productive FTE requirement and required date.","Define training, nesting, and post-nesting ramp assumptions.","Calculate the training starters required after training yield.","Calculate the accepted offers required after offer acceptance.","Backsolve training, onboarding, recruiting, and approval dates.","Validate recruiter, trainer, facility, system, and nesting-support constraints before approval."],
  example:{title:"Backsolving an October capacity need",facts:["Required capacity: 24 productive FTE by 1 October","Training duration: four weeks","Nesting duration: two weeks","Training yield: 85%","Offer acceptance: 80%","Recruiting lead time: six weeks"],analysis:"The plan requires 29 training starters and 37 accepted offers after rounding up. Four weeks of training, two weeks of nesting, and six weeks of recruiting place the launch approximately twelve weeks before 1 October.",decision:"Launch recruiting approximately twelve weeks before the productive date, protect capacity for at least 29 training starters, and verify that the two-week nesting period includes the full productivity ramp for this exercise."},
  mistakes:["Starting with the recruitment date instead of the required productive date","Rounding workforce requirements down","Ignoring training, nesting, or support-capacity limits","Assuming nesting always includes the full productivity ramp without stating the assumption"],
  quiz:[["Why should the hiring plan be backsolved from the productive date?",["Backsolving ensures every lead-time stage finishes before capacity is required.","Backsolving removes the need for training.","Backsolving guarantees every offer will be accepted."],0],["Why are training starters rounded up?",["Rounding up protects the minimum productive requirement after training yield.","Rounding up reduces the productive requirement.","Rounding up removes recruiting lead time."],0],["What must be clarified about the nesting period?",["The plan must state whether nesting includes the complete productivity ramp.","The plan must state only the nesting room color.","The plan must exclude nesting from the timeline."],0]],
  takeaways:["Backsolve all workforce actions from the required productive date.","Acceptance and training yield determine the required hiring funnel.","Ramp assumptions and support constraints must be explicit before approval."]
 },
 "Long-Range Capacity Strategy":{
  overview:"Long-range capacity strategy connects multi-year demand scenarios with workforce location, sourcing, technology, capability, and investment decisions. The planner preserves resilient options rather than relying on one precise distant forecast.",
  terms:[["Capacity portfolio","The mix of internal, external, site-based, remote, and flexible workforce capacity."],["Strategic horizon","The multi-year period used for structural workforce and investment decisions."],["Scenario trigger","A measurable condition that activates a predefined strategic response."],["Option value","The benefit of preserving flexibility when demand, technology, or workforce supply is uncertain."]],
  method:["Define base, upside, downside, and disruption demand scenarios.","Assess site, skill, sourcing, technology, and leadership constraints.","Design alternative capacity portfolios with implementation lead times.","Compare service resilience, total cost, workforce feasibility, and concentration risk.","Define measurable triggers, decision rights, and no-regret actions.","Recommend a staged roadmap with review dates and reversible decision points."],
  example:{title:"Three-year capacity portfolio",facts:["Current demand index: 100","Base demand growth: 4% annually","Upside demand growth: 9% annually","Automation may remove 12% of workload from Year 2","Primary site is near practical capacity","External partner activation requires six months"],analysis:"Primary-site expansion may be efficient under the base case but creates concentration and timing risk under the upside case. Automation may reduce workload, but the benefit should not be removed from the approved requirement before implementation is validated. Partner capacity provides faster contingency at a higher unit cost.",decision:"Use a staged portfolio that preserves partner contingency, validates automation benefits, and activates site expansion only when approved demand, utilization, service-risk, or concentration triggers are reached."},
  mistakes:["Treating one long-range scenario as certain","Ignoring implementation lead times and dependencies","Comparing options only on labor cost","Committing all capacity to one irreversible option too early"],
  quiz:[["Why should long-range capacity planning use multiple scenarios?",["Multiple scenarios show how uncertain assumptions change strategic workforce choices.","Multiple scenarios eliminate all uncertainty from the plan.","Multiple scenarios replace governance and approval."],0],["What is a scenario trigger?",["A scenario trigger is a measurable condition that activates a predefined response.","A scenario trigger is a duplicate historical record.","A scenario trigger is an employee schedule preference."],0],["Why should a capacity strategy preserve option value?",["Option value reduces the operational and financial cost of being wrong under uncertainty.","Option value guarantees the lowest immediate labor cost.","Option value removes every implementation deadline."],0]],
  takeaways:["Long-range capacity strategy balances cost, resilience, flexibility, and concentration risk.","Lead times and dependencies determine when strategic decisions must be made.","Scenario triggers convert uncertainty into governed action."]
 },
 "Financial Workforce Scenarios":{
  overview:"Financial workforce scenarios compare alternative ways to close capacity gaps using loaded cost, productive timing, service impact, flexibility, sustainability, and risk. The lowest unit rate is not always the best total decision.",
  terms:[["Loaded cost","The full workforce cost including pay, benefits, overhead, technology, facilities, and related expenses."],["Variable capacity","Workforce capacity that can expand or contract as demand changes."],["Scenario delta","The financial or operational difference between an option and the approved baseline."],["Break-even point","The duration, volume, or date at which two capacity options have equal total cost."]],
  method:["Define the productive-capacity gap, start date, and expected duration.","Create comparable internal hiring, partner, overtime, automation, and flexibility options.","Calculate recurring, one-time, implementation, and exit costs.","Model productivity, service impact, lead time, and workforce sustainability.","Test sensitivities, missing inputs, and break-even points.","Recommend an option or portfolio with triggers, limits, owners, and exit criteria."],
  example:{title:"Build, partner, or overtime",facts:["Gap: 20 productive FTE for six months","Internal loaded cost: 55,000 currency units per gross FTE-month","Partner cost: 68,000 currency units per productive FTE-month","Overtime premium: 35%","Internal hiring lead time: four months"],analysis:"The six-month exposure equals 120 productive FTE-months. Partner recurring cost is 8.16 million currency units before setup and exit charges. A simplified internal cost is lower, but it is not directly comparable because hiring lead time, training, ramp, and gross-to-productive conversion are incomplete. Overtime also lacks the base rate and sustainable-hours limit needed for a final comparison.",decision:"Use controlled partner capacity and limited overtime as a bridge. Approve internal hiring only if demand persists long enough to recover recruiting, training, and ramp costs, and define exit criteria for every temporary action."},
  mistakes:["Comparing options using only hourly or monthly rates","Ignoring recruitment, training, implementation, and ramp lead times","Using overtime as permanent structural capacity","Excluding setup, minimum-commitment, transition, and exit costs"],
  quiz:[["Why is the lowest workforce unit cost not always the best capacity choice?",["Timing, productivity, service impact, flexibility, and risk also determine total value.","Workforce unit cost is never relevant to capacity decisions.","The highest-cost option is always the safest choice."],0],["What does a financial break-even point identify?",["A break-even point identifies when two capacity options have equal total cost.","A break-even point identifies when forecast bias becomes zero.","A break-even point identifies when every employee completes training."],0],["Why should overtime scenarios include operating limits?",["Sustained overtime can create cost, fatigue, quality, and retention risk.","Overtime automatically reduces forecast workload.","Overtime eliminates shrinkage from the workforce plan."],0]],
  takeaways:["Capacity options should be compared on total economics and operational value.","Lead time and gap duration can change the preferred option.","Temporary bridge actions require limits, triggers, and exit criteria."]
 },
 "Capacity Governance":{
  overview:"Capacity governance establishes a repeatable operating rhythm for assumptions, plan versions, decisions, approvals, actions, and accountability. Effective governance ensures workforce actions occur before lead-time windows close and that plan changes remain traceable.",
  terms:[["Decision calendar","A controlled schedule of capacity decisions, deadlines, owners, dependencies, and approval gates."],["Assumption register","A record of material planning inputs, values, sources, owners, review dates, and status."],["Capacity version","An identified state of the approved demand, supply, gap, and action plan."],["Action tracker","A record of decisions, owners, milestones, expected impact, realized outcome, and residual risk."]],
  method:["Define planning products, horizons, grains, and required metadata.","Assign owners to demand, supply, financial, and workforce assumptions.","Establish version, review, approval, publication, and supersession controls.","Create a decision calendar aligned with hiring, training, budget, sourcing, and technology lead times.","Track approved actions, milestones, benefits, exceptions, and residual risks.","Review plan accuracy, decision effectiveness, and governance performance on a recurring cadence."],
  example:{title:"Monthly capacity-governance reset",facts:["Forecast and supply teams use different plan versions","Hiring approvals miss recruitment lead times","The attrition assumption has no named owner","Workforce actions are held only in meeting notes","Finance receives material changes after budget review"],analysis:"The organization lacks one governed capacity baseline, clear assumption ownership, an approval calendar, and a controlled action record. These weaknesses create avoidable staffing gaps and inconsistent financial commitments.",decision:"Implement one controlled repository, a stable Capacity Plan ID separate from lifecycle status, an assumption register, a decision calendar, approval evidence, and an action tracker through outcome review."},
  mistakes:["Treating governance as a meeting schedule rather than a control system","Allowing silent assumption or version changes","Recording decisions without owners, deadlines, or expected impact","Reviewing capacity performance only after action windows close"],
  quiz:[["What should a capacity decision calendar contain?",["It should contain decisions, deadlines, owners, dependencies, and approval gates.","It should contain only historical contact volume.","It should contain only employee scheduling preferences."],0],["Why is an assumption register required?",["Material assumptions need traceable sources, owners, review dates, and status.","An assumption register prevents every input from changing.","An assumption register replaces workforce and financial models."],0],["What should happen after a capacity action is approved?",["The action's milestones, outcomes, expected impact, and residual risks should be tracked.","The action record should be deleted after approval.","No further capacity review is required after approval."],0]],
  takeaways:["Capacity governance protects decision timing, traceability, and accountability.","Material assumptions and workforce actions require named owners and review dates.","Outcome review improves future capacity decisions and governance controls."]
 }
};


const analyticsLessonDetails={
 "Essential WFM Metrics":{
  overview:"Essential WFM metrics translate demand, workload, staffing, schedule, service, productivity, and employee outcomes into decision-ready measures. A metric is useful only when its definition, grain, owner, source, and intended decision are clear.",
  terms:[["Metric","A quantified measure used to describe performance or conditions."],["KPI","A metric selected to indicate progress toward a material objective."],["Target","The intended result for a metric over a defined period."],["Threshold","A boundary that triggers investigation, escalation, or action."]],
  method:["Clarify the decision the measure should support.","Define the metric name, purpose, formula, grain, and filters.","Identify the authoritative source and accountable owner.","Set target, threshold, and comparison period.","Segment results using relevant dimensions.","Review whether the metric drives the intended decision and behavior."],
  example:{title:"Building a WFM metric map",facts:["Service objective: 80% answered within 20 seconds","Forecast volume: 10,000 contacts","Actual volume: 10,800 contacts","Required staffing: 92 productive FTE","Available staffing: 86 productive FTE"],analysis:"Service performance alone cannot explain the result. Demand variance and productive staffing variance provide related evidence about the operating conditions behind service.",decision:"Use a linked metric set covering demand, workload, staffing, schedule execution, service, and action ownership instead of judging performance from one KPI."},
  mistakes:["Using a metric without a documented definition","Treating every available measure as a KPI","Comparing values with different grains or filters","Setting targets without clear action thresholds"],
  quiz:[["What distinguishes a KPI from a general metric?",["A KPI is selected because it indicates progress toward a material objective.","A KPI is any value available in a reporting tool.","A KPI never requires a target or owner."],0],["Why should a metric include a defined grain?",["The grain clarifies the level of detail represented by each value.","The grain automatically improves performance.","The grain replaces the metric formula."],0],["What should happen when a threshold is crossed?",["The approved investigation, escalation, or action process should begin.","The metric definition should be deleted.","The result should always be ignored until month end."],0]],
  takeaways:["Metrics should connect directly to decisions.","Definitions, sources, grain, and ownership create trust.","A balanced metric set explains more than a single KPI."]
 },
 "Understanding Variance":{
  overview:"Variance analysis compares planned, expected, or target performance with actual results. The analyst separates the size and direction of variance from the operational drivers that created it.",
  terms:[["Variance","The signed difference between an actual result and its comparison value."],["Materiality","The degree to which a difference is large enough to affect a decision."],["Driver","A factor that contributes to the observed result."],["Variance bridge","A structured explanation of how individual drivers move a result from plan to actual."]],
  method:["Confirm the comparison basis, sign convention, period, and grain.","Calculate signed and absolute variance.","Test whether the variance is material.","Decompose the result into demand, workload, staffing, schedule, and execution drivers.","Validate drivers with supporting evidence.","Recommend an action, owner, timing, and measure of success."],
  example:{title:"Explaining a service miss",facts:["Forecast volume: 10,000; actual volume: 10,800","Forecast AHT: 420 seconds; actual AHT: 441 seconds","Required productive FTE: 92","Available productive FTE: 86","Service result: 68% versus 80% target"],analysis:"Volume is 8% above forecast, AHT is 5% above forecast, and available staffing is six productive FTE below requirement. These drivers combine to increase workload and reduce service capacity.",decision:"Quantify each driver, separate planning error from execution loss, and assign corrective actions to the appropriate owners."},
  mistakes:["Reporting a variance without its sign convention","Treating correlation as confirmed cause","Ignoring materiality and timing","Combining unrelated drivers into one explanation"],
  quiz:[["What does a signed variance show?",["A signed variance shows both the size and direction of the difference.","A signed variance shows only the absolute size of the difference.","A signed variance replaces root-cause analysis."],0],["Why should materiality be assessed?",["Materiality helps determine whether a variance warrants attention or action.","Materiality guarantees that the variance has one cause.","Materiality removes the need for evidence."],0],["What is the purpose of a variance bridge?",["A variance bridge explains how individual drivers move performance from plan to actual.","A variance bridge combines all data into one unclassified total.","A variance bridge replaces metric definitions."],0]],
  takeaways:["Variance describes a difference, not automatically its cause.","Materiality and timing determine decision relevance.","Driver evidence should support every recommended action."]
 },
 "Metric Definitions and Data Quality":{
  overview:"Metric definitions and data-quality controls ensure that WFM measures are repeatable, comparable, and trusted. Analysts document formulas, grain, filters, timing, ownership, and reconciliation rules before publishing results.",
  terms:[["Metric dictionary","A controlled record of metric definitions and calculation rules."],["Data lineage","The traceable path from source data to the reported result."],["Reconciliation","A control that compares related totals or systems and explains differences."],["Data-quality rule","A test for completeness, validity, consistency, uniqueness, or timeliness."]],
  method:["Define the business question and metric purpose.","Document the formula, grain, filters, dimensions, and exclusions.","Identify source systems, data lineage, and the accountable owner.","Create completeness, validity, consistency, uniqueness, and timeliness checks.","Reconcile related totals and investigate exceptions.","Approve, version, publish, and periodically review the definition."],
  example:{title:"Defining forecast accuracy",facts:["Forecast source: planning system","Actual source: routing platform","Daily and interval views exist","Canceled contacts are inconsistently filtered","Two reports use opposite Actual-minus-Forecast sign conventions"],analysis:"Without aligned filters, grain, and sign conventions, the reports cannot be compared reliably even when each calculation runs correctly.",decision:"Create one approved metric definition, reconcile source totals, standardize filters and sign convention, and version the metric-dictionary entry before publication."},
  mistakes:["Documenting a formula without grain or filters","Using multiple sources without reconciliation","Changing metric definitions silently","Publishing incomplete or stale data without a clear warning"],
  quiz:[["What should a metric dictionary contain in addition to a formula?",["It should contain purpose, grain, filters, sources, ownership, and calculation rules.","It should contain only the report color and layout.","It should contain employee scheduling preferences only."],0],["What does data lineage provide?",["Data lineage provides a traceable path from source data to the reported result.","Data lineage guarantees that every value meets its target.","Data lineage replaces data-quality testing."],0],["Why is reconciliation required?",["Reconciliation identifies and explains differences between related data views or systems.","Reconciliation removes the need for source ownership.","Reconciliation automatically corrects every error."],0]],
  takeaways:["A metric is trustworthy only when its definition is complete.","Data lineage and reconciliation make results auditable.","Definition changes require version control and communication."]
 },
 "Forecast, Staffing, and Schedule Analysis":{
  overview:"Integrated WFM analysis connects forecast demand, workload requirements, scheduled staffing, and actual productive staffing to identify where an operating gap originated and which team owns the corrective action.",
  terms:[["Planning layer","A stage of the WFM process, such as forecast, capacity, schedule, or intraday execution."],["Workload variance","The difference between actual workload and forecast workload."],["Coverage variance","The difference between scheduled productive staffing and required productive staffing."],["Execution variance","The difference between actual productive staffing and scheduled productive staffing."]],
  method:["Confirm the service issue, period, channel, skill, and comparison basis.","Compare forecast workload with actual workload to assess demand and handling-time impact.","Compare required productive staffing with scheduled productive staffing to assess planning coverage.","Compare scheduled productive staffing with actual productive staffing to assess execution loss.","Reconcile the component variances without double counting the same impact.","Assign evidence-based actions to Forecasting, Capacity Planning, Scheduling, or Operations."],
  example:{title:"Tracing a service miss through WFM layers",facts:["Forecast workload: 1,200 hours","Actual workload: 1,320 hours","Required productive staffing: 90 FTE","Scheduled productive staffing: 87 FTE","Actual productive staffing: 82 FTE","Service result: 69% versus 80% target"],analysis:"Actual workload is 120 hours above forecast. Scheduled staffing is three productive FTE below requirement, and actual productive staffing is five productive FTE below schedule. The eleven-percentage-point service miss therefore reflects combined workload, planning-coverage, and execution pressure rather than one isolated failure.",decision:"Quantify each layer separately, validate the underlying drivers, reconcile the staffing gaps, and assign corrective actions to the accountable owners without double counting the same impact."},
  mistakes:["Attributing the full service miss to one planning layer","Comparing values with different periods, skills, or FTE definitions","Double counting workload and staffing impacts","Assigning actions before validating the driver evidence"],
  quiz:[["Why should forecast, staffing, and schedule results be analyzed together?",["The combined view shows which WFM layers contributed to the operating result.","The combined view guarantees that Forecasting caused the service miss.","The combined view removes the need to validate data."],0],["What does execution variance compare?",["Execution variance compares actual productive staffing with scheduled productive staffing.","Execution variance compares forecast volume with actual volume.","Execution variance compares required staffing with budget."],0],["Why should analysts avoid double counting?",["The same workload or staffing effect should not be attributed to multiple drivers more than once.","Double counting makes every result easier to explain.","Double counting is required when several teams are involved."],0]],
  takeaways:["Integrated analysis separates workload, planning-coverage, and execution effects.","All comparisons must use aligned periods, skills, and units.","Corrective actions should follow validated ownership of each driver."]
 },
 "Building a WFM Dashboard":{
  overview:"A WFM dashboard organizes trusted measures into a decision-focused view. An effective dashboard highlights current status, material trends, exceptions, ownership, and drill paths instead of displaying every available metric.",
  terms:[["Visual hierarchy","The use of layout, scale, and emphasis to direct attention to the most important information."],["Exception view","A focused display of results outside approved targets or thresholds."],["Drill path","A controlled route from a summary measure to detailed supporting evidence."],["Dashboard latency","The time between an operational event and its availability in the dashboard."]],
  method:["Clarify the users, decisions, planning horizon, and review cadence.","Select a balanced set of outcome, driver, and control metrics.","Define targets, thresholds, sources, refresh timing, grain, and ownership.","Arrange measures using a clear visual hierarchy and consistent conventions.","Add segmentation and drill paths for material exceptions.","Test readability, actionability, latency, accessibility, and user interpretation before release."],
  example:{title:"Redesigning a weekly WFM dashboard",facts:["Audience: Operations, WFM, and Finance","Review duration: 30 minutes","Current report: 38 metrics on one page","Primary outcomes: service, labor cost, and schedule stability","Driver measures: forecast accuracy, staffing gap, schedule efficiency, and adherence","Six metrics are outside approved thresholds"],analysis:"The current report is too dense for a thirty-minute decision meeting. The dashboard requires a concise outcome layer, a focused exception layer, and drill paths that connect each material result with its operational drivers.",decision:"Create an executive summary with six primary measures, a WFM driver page, and detailed drill views. Assign every exception a threshold, accountable owner, required action, and review date."},
  mistakes:["Displaying every available metric on one page","Using color without a documented threshold meaning","Mixing daily, weekly, and monthly grains without clear labels","Showing status without ownership, action, or a drill path"],
  quiz:[["What should determine which measures appear on a WFM dashboard?",["The users and decisions the dashboard is designed to support should determine the measures.","Every field available in the source system should appear on the dashboard.","The dashboard should include enough measures to fill all available space."],0],["What is the purpose of a dashboard drill path?",["A drill path connects a summary exception with detailed supporting evidence.","A drill path replaces the approved metric definition.","A drill path prevents users from reviewing source detail."],0],["Why should dashboard latency be disclosed?",["Users need to understand how current the information is before making a decision.","Latency determines the dashboard color palette.","Latency removes the need for data-quality controls."],0]],
  takeaways:["Dashboards should be designed around decisions, users, and exceptions.","Visual hierarchy should direct attention to material outcomes and drivers.","Every threshold, owner, action, and drill path needs a clear business purpose."]
 }
};


