const capacityRefinements={
 "Workload and Productive Capacity":{
  objective:"Calculate workload, required productive FTE, and the signed capacity variance using consistent weekly units.",
  label:"Formula",
  formula:"Workload hours = Volume x AHT seconds / 3,600; Required productive FTE = Workload hours / Productive hours per FTE; Capacity variance = Available productive FTE - Required productive FTE",
  calculation:["Workload = 18,000 x 480 / 3,600 = 2,400 hours","Required productive FTE = 2,400 / 32 = 75.00 FTE","Capacity variance = 72 available - 75 required = -3.00 FTE","The negative result indicates a three-FTE productive-capacity deficit"],
  dataset:["Planning period: one week","Forecast volume: 18,000 contacts","AHT: 480 seconds","Productive hours per FTE: 32 per week","Available productive capacity: 72 FTE","Use productive FTE throughout the comparison and state the sign convention"],
  modelAnswer:"The forecast creates 2,400 workload hours. At 32 productive hours per FTE, the requirement is 75.00 productive FTE. Available capacity is 72 FTE, so the signed variance is -3.00 FTE. The planner should validate the demand, AHT, and productive-hours assumptions, quantify the service exposure, and assign a feasible action, owner, and review date for the three-FTE deficit."
 },
 "FTE and Shrinkage Basics":{
  objective:"Calculate gross FTE under low, base, and high shrinkage assumptions and explain the resulting sensitivity.",
  label:"Formula",
  formula:"Gross FTE = Productive FTE / (1 - Shrinkage rate)",
  calculation:["At 20% shrinkage: 80 / (1 - 0.20) = 80 / 0.80 = 100.00 gross FTE","At 25% shrinkage: 80 / (1 - 0.25) = 80 / 0.75 = 106.67 gross FTE","At 30% shrinkage: 80 / (1 - 0.30) = 80 / 0.70 = 114.29 gross FTE","Sensitivity range = 114.29 - 100.00 = 14.29 gross FTE"],
  dataset:["Productive workforce requirement: 80 FTE","Low shrinkage assumption: 20%","Approved base shrinkage assumption: 25%","High shrinkage assumption: 30%","Round displayed FTE results to two decimal places","Document the activities included in each shrinkage assumption"],
  modelAnswer:"The gross requirement is 100.00 FTE at 20% shrinkage, 106.67 FTE at the approved 25% base assumption, and 114.29 FTE at 30% shrinkage. The ten-point shrinkage range changes the gross requirement by 14.29 FTE. Use 106.67 gross FTE for the base plan, retain the low and high cases as sensitivity boundaries, and document the shrinkage categories and assumption owner."
 },
 "Understanding Staffing Gaps":{
  objective:"Build a signed three-month staffing-gap view and identify the required workforce decision timing.",
  label:"Formula",
  formula:"Staffing gap = Available productive FTE - Required productive FTE",
  calculation:["January gap = 124 available - 120 required = +4 FTE surplus","February gap = 123 available - 126 required = -3 FTE deficit","March gap = 124 available - 132 required = -8 FTE deficit","An eight-week recruitment lead time means the March workforce decision must be approved at least eight weeks before productive capacity is required"],
  dataset:["January: 120 required productive FTE and 124 available productive FTE","February: 126 required productive FTE and 123 available productive FTE","March: 132 required productive FTE and 124 available productive FTE","External recruitment lead time: eight weeks","Identify the first deficit, largest deficit, bridge action, owner, and decision deadline"],
  modelAnswer:"January has a +4 FTE surplus, February has a -3 FTE deficit, and March has a -8 FTE deficit. February is the first risk period and needs a short-term bridge because external recruitment cannot respond in time. March is the largest gap, so the hiring decision must be approved at least eight weeks before the required productive date. Do not offset deficits with January surplus unless timing, skill, and location are compatible."
 },
 "Weekly and Monthly Capacity Planning":{
  objective:"Reconcile weekly productive FTE requirements to the approved monthly capacity plan and quantify temporary weekly supply gaps.",
  label:"Formula",
  formula:"Weekly requirement = Monthly FTE-weeks x Weekly requirement share; Weekly gap = Available productive FTE - Weekly required productive FTE",
  calculation:["Week 1 requirement = 400 x 23% = 92 FTE; gap = 94 - 92 = +2 FTE","Week 2 requirement = 400 x 24% = 96 FTE; gap = 96 - 96 = 0 FTE","Week 3 requirement = 400 x 26% = 104 FTE; adjusted supply = 99 - 5 training = 94 FTE; gap = 94 - 104 = -10 FTE","Week 4 requirement = 400 x 27% = 108 FTE; gap = 102 - 108 = -6 FTE"],
  dataset:["Approved monthly requirement: 400 FTE-weeks","Weekly requirement shares: 23%, 24%, 26%, and 27%","Available productive supply: 94, 96, 99, and 102 FTE","Training removes five productive FTE in Week 3","Identify weekly gaps, the first decision point, and actions that preserve monthly reconciliation"],
  modelAnswer:"Weekly requirements are 92, 96, 104, and 108 productive FTE and reconcile to 400 FTE-weeks. After the Week 3 training reduction, weekly gaps are +2, 0, -10, and -6 FTE. Protect Week 3 through a feasible activity move or temporary capacity action, assign a Week 4 mitigation, and refresh both demand and supply assumptions in the next planning cycle."
 },
 "Workforce Supply Projection":{
  objective:"Build a four-month productive FTE supply waterfall using continuing-workforce attrition, time-phased new-hire ramp, and outbound transfers.",
  label:"Supply framework",
  formula:"Ending productive FTE = Continuing-workforce productive FTE after attrition + Ramp-adjusted new-hire productive FTE + Transfers in - Transfers out + Returns",
  calculation:["Month 1 continuing-workforce productive FTE = 200.00 x (1 - 2%) = 196.00","Month 2 continuing-workforce productive FTE = 196.00 x (1 - 2%) = 192.08; the twenty new hires contribute 0.00 productive FTE while starting and training","Month 3 continuing-workforce productive FTE = 192.08 x (1 - 2%) = 188.24; new-hire productive FTE = 20 x 50% = 10.00; ending productive FTE = 198.24","Month 4 continuing-workforce productive FTE = 188.24 x (1 - 2%) = 184.48; new-hire productive FTE = 20 x 80% = 16.00; outbound transfers = 5.00 productive FTE; ending productive FTE = 195.48"],
  dataset:["Opening continuing-workforce productive FTE: 200.00","Monthly attrition: 2%, applied only to the continuing-workforce productive FTE base in this exercise","Twenty new hires start in Month 2 and contribute 0.00 productive FTE during starting and training","New-hire productive contribution: 50% in Month 3 and 80% in Month 4","Five productive FTE transfer out in Month 4","Exercise assumption: the new-hire cohort does not experience additional attrition during the four-month example","A production plan should model new-hire cohort attrition separately when a supported assumption is available","Keep continuing-workforce productive FTE, new-hire productive FTE, and transfers as separate waterfall lines"],
  modelAnswer:"The continuing-workforce productive FTE declines to 196.00 in Month 1, 192.08 in Month 2, 188.24 in Month 3, and 184.48 in Month 4. New hires contribute 0.00 productive FTE in Month 2, 10.00 productive FTE in Month 3, and 16.00 productive FTE in Month 4. After subtracting five outbound productive FTE in Month 4, ending productive FTE is 195.48. This exercise applies attrition only to the continuing-workforce base and assumes no additional new-hire cohort attrition during the four-month window. In a production plan, model new-hire attrition separately when a supported cohort assumption exists."
 },
 "Hiring, Training, and Ramp Planning":{
  objective:"Backsolve the recruitment calendar and calculate the accepted offers and training starters required to deliver 24 productive FTE by 1 October.",
  label:"Formula",
  formula:"Required training starters = Required productive FTE / Training yield; Required accepted offers = Required training starters / Offer acceptance",
  calculation:["Required training starters = 24 productive FTE / 85% training yield = 28.24, rounded up to 29 starters","Required accepted offers = 29 starters / 80% offer acceptance = 36.25, rounded up to 37 accepted offers","Training plus nesting = four weeks + two weeks = six weeks before 1 October","Recruiting lead time adds six weeks, so the recruiting launch is approximately twelve weeks before 1 October"],
  dataset:["Required capacity: 24 productive FTE by 1 October","Training duration: four weeks","Nesting duration: two weeks","Training yield: 85%","Offer acceptance: 80%","Recruiting lead time: six weeks","Exercise assumption: the two-week nesting period includes the full productivity ramp, and employees who complete nesting are treated as fully productive","If full productivity requires additional ramp time, add that duration before backsolving training, onboarding, and recruiting dates","Identify the recruiting launch, minimum accepted offers, minimum training starters, support constraints, and evidence required before approval"],
  modelAnswer:"Plan at least 29 training starters and 37 accepted offers. The exercise assumes the two-week nesting period includes the full productivity ramp, so employees who complete nesting are treated as fully productive by 1 October. Backsolve six weeks of training and nesting from 1 October, then another six weeks for recruiting and onboarding, placing the recruiting launch approximately twelve weeks before the productive date. If the real operation requires additional post-nesting ramp time, add that duration before backsolving all earlier dates. Confirm recruiter throughput, trainer capacity, learning space, system access, nesting support, early attrition assumptions, and the rounding policy before approval."
 },
 "Long-Range Capacity Strategy":{
  objective:"Compare three-year capacity portfolios and define measurable triggers for partner, automation, and site decisions.",
  label:"Decision framework",
  formula:"Strategic capacity decision = Demand fit + Service resilience + Total cost + Lead time + Workforce feasibility + Risk + Option value",
  calculation:["Base demand index: Year 1 = 100.00; Year 2 = 100 x 1.04 = 104.00; Year 3 = 104 x 1.04 = 108.16","Upside demand index: Year 1 = 100.00; Year 2 = 100 x 1.09 = 109.00; Year 3 = 109 x 1.09 = 118.81","If validated automation removes 12% of Year 2 workload, adjusted base Year 2 index = 104 x 0.88 = 91.52 and adjusted upside Year 2 index = 109 x 0.88 = 95.92","The six-month partner lead time requires an activation trigger and approval date before the capacity risk materializes"],
  dataset:["Current demand index: 100","Base annual demand growth: 4%","Upside annual demand growth: 9%","Potential automation benefit: 12% workload reduction beginning in Year 2 only after benefit validation","The primary site is near practical capacity","External partner activation lead time: six months","Compare primary-site expansion, partner contingency, automation, remote capacity, and a staged portfolio"],
  modelAnswer:"A staged capacity portfolio is more resilient than one irreversible option. Under the base case, the demand index reaches 104.00 in Year 2 and 108.16 in Year 3. Under the upside case, the index reaches 109.00 in Year 2 and 118.81 in Year 3. If the 12% automation benefit is validated before Year 2, the adjusted Year 2 indexes are 91.52 for the base case and 95.92 for the upside case. Preserve partner contingency for near-term upside risk, do not remove automation workload before benefits are proven, and activate site expansion only when approved demand, utilization, service-risk, or concentration triggers are reached. Publish each trigger, owner, approval deadline, lead time, and fallback action."
 },
 "Financial Workforce Scenarios":{
  objective:"Compare build, partner, and overtime scenarios using total cost, productive timing, sustainability, and exit criteria.",
  label:"Financial decision framework",
  formula:"Scenario value = Recurring loaded cost + One-time cost + Timing impact + Productivity impact + Service risk + Exit cost",
  calculation:["Gap exposure = 20 productive FTE x 6 months = 120 productive FTE-months","Partner recurring cost = 120 x 68,000 = 8,160,000 currency units, excluding setup, transition, minimum-commitment, and exit costs","Internal hiring lead time = four months, leaving at most two productive months within the six-month gap before training and ramp are considered","Internal six-month gross-FTE cost at full availability = 20 x 55,000 x 6 = 6,600,000 currency units, but this is not a valid gap-coverage comparison because hiring is unavailable during the lead-time period and productive conversion is not supplied","A complete overtime cost cannot be calculated until the base labor rate, feasible overtime hours, productivity effect, and sustainability limit are supplied"],
  dataset:["Capacity gap: 20 productive FTE for six months","Internal loaded cost: 55,000 currency units per gross FTE-month","Partner cost: 68,000 currency units per productive FTE-month","Overtime premium: 35% above the applicable base labor rate","Internal hiring lead time: four months before training and ramp","Internal productive conversion, recruitment cost, training cost, partner setup cost, and overtime base rate are not supplied","Identify missing inputs, total-cost boundaries, feasible bridge actions, approval triggers, and exit criteria"],
  modelAnswer:"The six-month exposure is 120 productive FTE-months. Partner recurring cost is 8.16 million currency units before setup, transition, minimum-commitment, and exit charges. A simple internal six-month cost of 6.60 million is not directly comparable because internal hiring is unavailable for the four-month lead time and the gross-to-productive conversion, training duration, ramp curve, and recruitment cost are missing. Overtime may support an immediate bridge, but its total cost is not valid until the base labor rate, feasible hours, productivity effect, and sustainability limits are defined. Use controlled partner capacity and limited overtime as a bridge, and approve internal hiring only if demand persists long enough to recover recruitment, training, and ramp costs. Assign owners, trigger dates, operating limits, and exit criteria to every temporary action."
 },
 "Capacity Governance":{
  objective:"Design a governed capacity-planning operating model with version control, assumption ownership, decision timing, approval evidence, and action tracking.",
  label:"Governance framework",
  formula:"Governed capacity plan = Versioned demand + Versioned supply + Owned assumptions + Decision calendar + Approval record + Action tracker",
  calculation:["Control 1: create one controlled repository for demand, supply, gaps, scenarios, decisions, approvals, and actions","Control 2: separate the stable Capacity Plan ID from lifecycle status so status changes do not alter the permanent identifier","Control 3: assign every material assumption a source, value, effective period, owner, review date, and status","Control 4: schedule hiring, training, budget, sourcing, technology, and location approvals before their lead-time deadlines","Control 5: track each approved action through owner, milestone, expected impact, realized outcome, residual risk, evidence, and closure"],
  dataset:["Forecast and workforce-supply teams currently use different plan versions","Hiring decisions regularly miss recruitment lead-time deadlines","The attrition assumption has no named owner or review date","Workforce actions are stored only in meeting notes","Finance receives material plan changes after budget review","Required lifecycle statuses: Draft, Under review, Approved, Published, Superseded, and Archived","Design the repository, stable plan ID, lifecycle status, assumption register, decision calendar, approval evidence, and action tracker"],
  modelAnswer:"Implement one governed capacity baseline in a controlled repository. Use Capacity Plan ID: CAP-PH-2027M01-v03 and Lifecycle status: APPROVED as separate fields. The assumption register should capture each material input's source, value, effective period, owner, review date, and status. The decision calendar should include workforce and financial decisions, dependencies, approval gates, and lead-time deadlines. The action tracker should record the decision, owner, milestone, expected impact, realized outcome, residual risk, evidence, and closure status. Review plan accuracy, action outcomes, missed decision windows, and governance effectiveness every month."
 }
};


const forecastingRefinements={
 "Volume, AHT, and Workload":{objective:"Calculate channel workload with correct units and explain driver sensitivity.",label:"Formula",formula:"Workload hours = Volume x AHT seconds / 3,600",calculation:["Voice = 1,200 x 420 / 3,600 = 140.00 hours","Chat raw = 800 x 600 / 3,600 = 133.33 hours","Email = 500 x 480 / 3,600 = 66.67 hours","Raw workload is not yet a staffing requirement"],dataset:["Voice: 1,200 contacts at 420 seconds","Chat: 800 contacts at 600 seconds; concurrency is not supplied","Email: 500 contacts at 480 seconds","Calculate raw workload only and identify the missing assumption"],modelAnswer:"Total raw workload is 340 hours. Do not calculate effective chat workload until an approved achieved-concurrency assumption is supplied. The next planning stages are raw workload, effective workload, productive staffing requirement, and gross staffing after shrinkage."},
 "Historical Data Preparation and Validation":{objective:"Produce an auditable clean-history decision log.",label:"Data-treatment framework",formula:"Adjusted history = Traceable raw history with approved retain, label, exclude, or replace treatments",calculation:["Remove validated duplicate records","Label the closure and routing outage","Retain and label the valid campaign uplift","Replace the missing interval only through an approved method"],dataset:["Forecast target: offered demand","One missing interval","Two duplicate records","One holiday closure and one routing outage","One valid campaign uplift of 22%","Treatment log fields: period, original value, issue, treatment, replacement, reason, evidence, owner, approval date"],modelAnswer:"Preserve the raw dataset. Remove only validated duplicates, label the closure and outage, retain the genuine campaign signal, and document the missing-interval replacement. Record every treatment with evidence, ownership, and approval."},
 "Forecasting Fundamentals":{objective:"Select and defend a transparent baseline against a benchmark.",label:"Formula",formula:"Four-period average = Sum of four actual periods / 4",calculation:["Total = 9,800 + 10,100 + 10,000 + 10,300 = 40,200","Four-period average = 40,200 / 4 = 10,050","Latest-period naive benchmark = 10,300","Accuracy superiority cannot be claimed until actual demand is available"],dataset:["Recent actuals: 9,800; 10,100; 10,000; 10,300","No structural change","No known future event","Compare the 10,050 average with the 10,300 naive benchmark after actual demand arrives"],modelAnswer:"Use 10,050 as the working baseline because recent demand is stable and no event is expected. Retain 10,300 as the naive benchmark and compare both methods when actual demand becomes available."},
 "Trends, Seasonality, Events, and Anomalies":{objective:"Classify demand movements and prevent double counting.",label:"Adjustment framework",formula:"Adjusted forecast = Baseline adjusted through one governed additive or multiplicative method",calculation:["Monday uplift = recurring seasonality","December uplift = recurring seasonality","Campaign uplift = event effect","Quarterly growth = trend","Routing outage = anomaly in observed handling"],dataset:["Mondays average 12% above the weekday baseline","December produces a recurring 20% uplift","Campaign adds 15% for two weeks","Underlying demand grows 2% per quarter","One routing outage reduced handled contacts","Task: classify effects and identify possible overlap"],modelAnswer:"Model trend, recurring seasonality, and the event separately. Do not treat outage handling as true demand. Before combining December and campaign assumptions, confirm whether either effect is already embedded in the baseline and use the approved additive or multiplicative method only once."},
 "Interval Forecasting":{objective:"Disaggregate daily demand and reconcile rounding.",label:"Formula",formula:"Interval forecast = Daily forecast x Interval profile share",calculation:["09:00 = 82.96, rounded to 83; 09:30 = 103.70, rounded to 104","10:00 = 124.44, rounded to 124; 10:30 = 145.18, rounded to 145","11:00 = 165.92, rounded to 166; 11:30 = 155.55, rounded to 156","12:00 = 134.81, rounded to 135; 12:30 = 124.44, rounded to 124; total = 1,037"],dataset:["Daily forecast: 1,037 contacts","09:00 8%; 09:30 10%; 10:00 12%","10:30 14%; 11:00 16%; 11:30 15%; 12:00 13%; 12:30 12%","Profile shares total 100%","Use a controlled largest-remainder method and retain unrounded values"],modelAnswer:"One valid reconciled allocation is 09:00 83, 09:30 104, 10:00 124, 10:30 145, 11:00 166, 11:30 156, 12:00 135, and 12:30 124. The rounded total is exactly 1,037. Retain both unrounded and rounded values for auditability."},
 "Forecast Accuracy and Bias":{objective:"Calculate WAPE and bias with one sign convention.",label:"Formula",formula:"WAPE % = Sum absolute error / Sum actual x 100; Bias % = Sum(Actual - Forecast) / Sum actual x 100",calculation:["Errors = +10, -20, +10, +10","Absolute error total = 50; actual total = 430","WAPE = 50 / 430 x 100 = 11.63%","Bias units = +10; Bias % = 10 / 430 x 100 = +2.33%"],dataset:["Period 1: forecast 100, actual 110","Period 2: forecast 120, actual 100","Period 3: forecast 90, actual 100","Period 4: forecast 110, actual 120","Sign convention: Actual minus Forecast"],modelAnswer:"WAPE is 11.63%. Bias is +10 units or +2.33%, showing slight underforecasting under the stated convention. Investigate Period 2 because it has the largest absolute error."},
 "Advanced Multi-Channel Forecasting":{objective:"Calculate effective workload by channel.",label:"Simplified formula",formula:"Simplified effective chat workload = Volume x AHT / 3,600 / Achieved concurrency",calculation:["Voice = 900 x 420 / 3,600 = 105 hours","Chat raw = 600 x 720 / 3,600 = 120 hours; simplified effective = 60 hours","Email arrivals = 45 hours; opening backlog = 9 hours","Total email workload = 54 hours"],dataset:["Voice: 900 at 420 seconds","Chat: 600 at 720 seconds; achieved concurrency 2","Email: 300 at 540 seconds","Opening email backlog: 60 at 540 seconds","Simplifying assumption: all chat effort is concurrency-eligible"],modelAnswer:"Plan 105 voice hours, 60 simplified effective chat hours, and 54 email hours. State that the chat result assumes all effort is concurrency-eligible. A stronger model separates non-concurrent effort from concurrent-eligible effort before division."},
 "Forecast Communication and Review":{objective:"Present scenarios with owners, deadlines, uncertainty, and workforce impact.",label:"Formula",formula:"Workload hours = Contacts x AHT / 3,600; Productive FTE = Workload hours / 140; Gross FTE = Productive FTE / (1 - 28%); Monthly cost = Gross FTE x 60,000",calculation:["Downside: 98,000 contacts = 11,433.33 workload hours = 81.67 productive FTE = 113.43 gross FTE = approximately 6.81 million currency units","Base: 104,000 contacts = 12,133.33 workload hours = 86.67 productive FTE = 120.37 gross FTE = approximately 7.22 million currency units","Upside: 109,000 contacts = 12,716.67 workload hours = 90.83 productive FTE = 126.16 gross FTE = approximately 7.57 million currency units","Scenario-based demand range = 98,000 to 109,000 contacts; this is a judgmental planning range, not a statistical confidence interval"],dataset:["Baseline demand: 100,000; base +4%; upside +9%; downside -2%","AHT: 420 seconds; productive hours per FTE: 140 per month","Shrinkage: 28%; monthly loaded cost: 60,000 currency units per gross FTE","Campaign decision is pending; identify the owner, deadline, and capacity action for each scenario"],modelAnswer:"Present all three scenarios. Downside requires 11,433.33 workload hours, 81.67 productive FTE, 113.43 gross FTE, and approximately 6.81 million currency units monthly. Base requires 12,133.33 workload hours, 86.67 productive FTE, 120.37 gross FTE, and approximately 7.22 million. Upside requires 12,716.67 workload hours, 90.83 productive FTE, 126.16 gross FTE, and approximately 7.57 million. State the rounding policy, identify the campaign owner and decision deadline, and define the workforce or cost action triggered by each scenario."},
 "Forecast Governance and Scenarios":{objective:"Design a traceable governance process.",label:"Governance framework",formula:"Governed forecast = Versioned data + Owned assumptions + Approved method + Decision record",calculation:["Use one controlled repository","Apply version IDs and status values","Register assumption owners and deadlines","Schedule approval, publication, accuracy, and learning reviews"],dataset:["Three forecast files currently circulate by email","Campaign assumption has no owner","Finance and Operations use different versions","Scenario names are inconsistent","Required metadata: ID, creation date, effective period, horizon, grain, scenario, status, owner, approver, superseded version, reason","Statuses: Draft, Under review, Approved, Published, Superseded, Archived"],modelAnswer:"Implement one governed repository, metadata and status standards, an assumption register, approval calendar, and monthly accuracy-and-learning review. Forecast ID: FCST-VOICE-PH-2027M01-v03. Lifecycle status: APPROVED. Keep the stable forecast ID separate from lifecycle status so the identifier does not change as the forecast moves through Draft, Under review, Approved, Published, Superseded, and Archived states."}
};


const schedulingRefinements={
 "Scheduling Fundamentals":{
  objective:"Produce a feasible draft shift plan and validate productive coverage after meals and breaks.",
  formula:"Coverage variance = Scheduled productive staffing - Required staffing",
  calculation:["Positive result = overcoverage","Zero = aligned coverage","Negative result = undercoverage"],
  dataset:["Requirement: 18 at 08:00, 21 at 09:00, 24 at 11:00-14:00, and 19 at 17:00","28 employees available: 16 on eight-hour shifts and 12 on six-hour shifts","Permitted starts: 08:00, 09:00, and 10:00","Meals begin after four hours and remove productive coverage"],
  modelAnswer:"Use staggered starts rather than one common start. Protect enough 09:00 and 10:00 starts to cover the 11:00-14:00 peak, then recalculate productive coverage after meal placement. Any negative interval variance must be documented and resolved or escalated."
 },
 "Shifts, Breaks, and Activities":{
  objective:"Recalculate productive interval coverage after all constrained and movable activities are placed.",
  formula:"Productive scheduled staffing = Scheduled staffing - Employees in nonproductive activities",
  calculation:["Place legally or contractually constrained activities first","Protect peak and scarce-skill intervals","Place movable activities only inside safe coverage windows"],
  dataset:["Peak: 11:30-13:30","Eight meals of 30 minutes; maximum two concurrent meals","Four coaching sessions of 30 minutes","Safe coaching windows: 09:30-11:00 and 14:30-16:00","Protected minimum productive staffing during peak: 22"],
  modelAnswer:"Stagger meals in batches no larger than two and keep coaching outside 11:30-13:30. After each placement, subtract concurrent activities from scheduled staffing and confirm productive coverage remains at or above 22."
 },
 "Reading a Coverage Chart":{
  objective:"Identify the earliest sustained coverage risk and recommend changes that improve the full-day plan.",
  formula:"Coverage variance = Scheduled productive staffing - Required staffing",
  calculation:["09:00 to 11:30 net interval variance: +4 +3 +0 -3 -5 -4 = -5 staffing-interval units","The total does not mean five employees are missing all day","Timing, duration, skill, and adjacency remain essential"],
  dataset:["09:00: +4","09:30: +3","10:00: 0","10:30: -3","11:00: -5","11:30: -4"],
  modelAnswer:"The operating risk begins at 10:30 and persists for three intervals. Test later starts and break movement using the early surplus, but validate that the change does not create a closing or skill-specific deficit."
 },
 "Shift and Break Optimization":{
  objective:"Quantify coverage improvement and disruption cost before recommending schedule changes.",
  formula:"Coverage gain = Deficit before change - Deficit after change",
  calculation:["Original peak deficit = -4","Two later starts recover 2","Two moved breaks recover 2","Revised peak variance = 0"],
  dataset:["Five-person surplus at 08:00-09:00","Four-person deficit at 12:00-13:00","Six shifts start at 08:00; two may move to 10:00","Two breaks may move by 30 minutes","No new closing deficit is permitted"],
  modelAnswer:"Move two eligible starts to 10:00 and move two breaks outside 12:00-13:00. The four-unit recovery closes the peak gap. Recheck the afternoon and closing intervals before publication."
 },
 "Schedule Rules and Constraints":{
  objective:"Diagnose an infeasible schedule and escalate the smallest unresolved structural gap.",
  formula:"Feasible schedule = All active hard constraints satisfied",
  calculation:["Legal and regulatory rules","Contractual and minimum-rest rules","Operational and skill requirements","Policies and employee preferences"],
  dataset:["Opening requirement: 10","Opening-eligible employees: 8","Minimum rest: 11 hours","Two additional employees ended too late to open compliantly","Overtime is not permitted"],
  modelAnswer:"The plan has a structural two-person opening gap. Do not violate minimum rest. Escalate the infeasibility and test approved alternatives such as changing prior-day endings, qualified flex coverage, or a revised operating requirement."
 },
 "Offline Activity Placement":{
  objective:"Set feasible batch sizes, preserve a coverage buffer, and define cancellation triggers.",
  formula:"Maximum removable capacity = Coverage surplus - Protected buffer",
  calculation:["Coverage surplus = 6","Protected buffer = 2","Maximum removable capacity = 4"],
  dataset:["Tuesday 09:00-10:30 surplus: +6","Protected buffer: +2","Training batch: 3 employees for 90 minutes","Meeting: 2 employees for 30 minutes","Coaching: 1 employee for 60 minutes"],
  modelAnswer:"A training batch of three is feasible and leaves a three-person surplus. The two-person meeting may overlap only if the protected buffer remains intact, so avoid overlapping it with the training batch. Cancel or move activity if projected coverage falls below +2."
 },
 "Multi-Skill Optimization":{
  objective:"Protect scarce-skill minimums while allocating shared capacity using effective, not nominal, supply.",
  formula:"Effective skill capacity = Eligible employees x Proficiency factor",
  calculation:["A-only: 9; B-only: 5; C-only: 4","A/B shared: 4; B/C shared: 3","Requirements: A 12, B 10, C 6"],
  dataset:["Queue A requires 12 specialists","Queue B requires 10 generalists","Queue C requires 6 bilingual employees","A-only 9, B-only 5, C-only 4","A/B-skilled 4 and B/C-skilled 3"],
  modelAnswer:"Assign at least three A/B employees to A and at least two B/C employees to C. Allocate the remaining shared capacity to B, then adjust for proficiency and routing. If effective B capacity remains below 10, document the residual risk."
 },
 "Schedule Efficiency and Fairness":{
  objective:"Defend a schedule choice using consistent operational, fairness, and stability measures.",
  formula:"Coverage efficiency = Covered required staffing intervals / Total required staffing intervals x 100",
  calculation:["Compare efficiency with preference fulfillment","Review late, weekend, and unfavorable-shift distribution","Include schedule-change rate, notice, and appeals"],
  dataset:["Option A: 94% efficiency and 62% preference fulfillment","Option B: 91% efficiency and 81% preference fulfillment","Option A assigns 70% of late shifts to one scheduling group","Option B distributes late shifts more evenly"],
  modelAnswer:"Prefer or refine Option B unless the three-point efficiency reduction creates material service risk. The decision should document the operational threshold, burden distribution, stability impact, and appeal process."
 },
 "Strategic Schedule Design":{
  objective:"Compare schedule-portfolio scenarios and recommend a controlled pilot with measurable success criteria.",
  formula:"Portfolio decision = Demand fit + Cost + Compliance + Workforce feasibility + Stability",
  calculation:["Compare current, staggered, and mixed portfolios","Test base, upside, and downside demand","Pilot before enterprise rollout"],
  dataset:["Current hours: 08:00-18:00; future hours: 07:00-22:00","Peak demand: 12:00-16:00","Low demand at opening and closing edges","Current model: mostly fixed eight-hour shifts","Part-time interest and voluntary extensions are available"],
  modelAnswer:"Pilot a mixed portfolio combining staggered full-time shifts, targeted part-time edge coverage, and controlled voluntary extensions. Measure coverage fit, labor cost, fill rate, preference fulfillment, stability, and implementation risk."
 }
};


const lessonFocus={
 "Introduction to Real-Time Management":["the purpose, scope, and decision cycle of intraday management","classify an event as monitor, investigate, or act","Create a 30-minute control-room checklist for a new Real-Time Analyst."],
 "Understanding the Intraday Plan":["required, scheduled, available, and actual staffing across intervals","reconcile the staffing plan with current operating conditions","Review six intervals and identify the first material staffing risk."],
 "Reading Queue and Service Indicators":["service level, ASA, queue, abandon rate, occupancy, and backlog","connect queue indicators instead of interpreting one metric alone","Diagnose a queue with rising ASA, stable arrivals, and worsening occupancy."],
 "Staffing Variance and Availability":["staffing variance, absence, shrinkage, skill availability, and net capacity","separate a headcount gap from a productive-capacity gap","Build a variance bridge from required staffing to actual available staffing."],
 "Real-Time Adherence Management":["schedule adherence, conformance, exceptions, and fair intervention","distinguish individual exceptions from systemic schedule problems","Prioritize five adherence exceptions and draft proportionate actions."],
 "Intraday Reforecasting and Recovery":["same-day demand updates, workload revision, and recovery options","reforecast remaining intervals and assess service impact","Reforecast the afternoon after volume and AHT exceed plan."],
 "Intraday Command and Recovery Plans":["structured command routines, triggers, owners, and recovery playbooks","choose actions using impact, reversibility, and lead time","Design a recovery plan for a multi-interval staffing deficit."],
 "Incident and Escalation Management":["incident classification, evidence, escalation, communication, and closure","build a concise decision-ready incident update","Create an escalation timeline for a technology outage affecting queues."],
 "Enterprise Real-Time Governance":["multi-site standards, decision rights, controls, and performance governance","define consistent guardrails while preserving local accountability","Draft governance standards for three regional control centers."],
 "Scheduling Fundamentals":["how staffing requirements become compliant employee schedules","identify the main inputs and outputs of schedule creation","Convert a simple requirement profile into a basic shift plan."],
 "Shifts, Breaks, and Activities":["shift structure, meals, breaks, meetings, coaching, and training placement","place activities without creating avoidable coverage gaps","Adjust breaks and a team meeting around a midday demand peak."],
 "Reading a Coverage Chart":["required versus scheduled staffing and interval coverage variance","locate overstaffed and understaffed intervals and explain why they matter","Interpret a coverage chart and recommend three schedule changes."],
 "Shift and Break Optimization":["optimization of start times, shift lengths, breaks, and lunches","improve coverage while respecting employee and work-rule constraints","Optimize six shifts against an uneven interval requirement."],
 "Schedule Rules and Constraints":["hard rules, soft preferences, contracts, skills, and legal constraints","resolve conflicts without violating mandatory rules","Classify ten constraints and resolve an infeasible schedule."],
 "Offline Activity Placement":["placement of training, coaching, meetings, and project time","use coverage surplus and risk thresholds to place offline work","Schedule four offline activities across a constrained week."],
 "Multi-Skill Optimization":["skill matrices, routing interactions, proficiency, and cross-skill allocation","balance specialist coverage with shared-pool flexibility","Allocate multi-skilled employees across three contact queues."],
 "Schedule Efficiency and Fairness":["coverage efficiency, stability, preference fulfillment, and equitable outcomes","evaluate efficiency and fairness together using transparent measures","Compare two schedules and recommend the fairer sustainable option."],
 "Strategic Schedule Design":["schedule portfolios, flexible patterns, operating models, and long-term demand fit","design schedule patterns that remain resilient as demand changes","Propose a future schedule portfolio for extended operating hours."],
 "Volume, AHT, and Workload":["the relationship among contacts, average handle time, and workload","calculate workload and explain the operational effect of each driver","Calculate workload for three channels and compare the results."],
 "Historical Data Preparation and Validation":["data completeness, interval alignment, outliers, closures, and event labels","clean history without erasing legitimate demand signals","Audit a historical dataset and document all adjustments."],
 "Forecasting Fundamentals":["baseline methods, assumptions, forecast horizons, and demand uncertainty","select a simple method appropriate to the available history","Create and explain a baseline forecast from recent observations."],
 "Trends, Seasonality, Events, and Anomalies":["recurring patterns, structural movement, known events, and abnormal observations","separate repeatable demand patterns from one-time effects","Classify a year of demand changes and propose adjustments."],
 "Interval Forecasting":["intraday profiles, day-of-week shape, interval distribution, and reconciliation","disaggregate totals while preserving daily and weekly consistency","Build an interval forecast from a daily volume estimate."],
 "Forecast Accuracy and Bias":["error, absolute error, WAPE, bias, and forecast-value interpretation","diagnose whether error is random, directional, or concentrated","Calculate accuracy and bias for four weeks and recommend action."],
 "Advanced Multi-Channel Forecasting":["voice, chat, messaging, email, concurrency, and channel interaction","model workload using channel-specific handling characteristics","Create a coordinated forecast for voice, chat, and email."],
 "Forecast Communication and Review":["assumptions, confidence, scenarios, risks, and stakeholder challenge","present a forecast as a decision narrative rather than a single number","Prepare a forecast review for Operations and Finance."],
 "Forecast Governance and Scenarios":["ownership, version control, approval, assumptions, and scenario governance","design controls that make forecasts traceable and actionable","Define a monthly forecast governance and scenario process."],
 "Workload and Productive Capacity":["workload conversion, productive hours, utilization, and capacity demand","translate workload into productive workforce requirements","Calculate productive capacity for a weekly workload plan."],
 "FTE and Shrinkage Basics":["headcount, paid FTE, productive FTE, shrinkage, and gross-up logic","calculate gross FTE from productive demand and shrinkage","Compare staffing needs under three shrinkage assumptions."],
 "Understanding Staffing Gaps":["demand, supply, surplus, deficit, timing, and materiality","identify when and where a gap requires action","Build a monthly gap view and flag the first decision point."],
 "Weekly and Monthly Capacity Planning":["time-phased demand, supply, seasonality, and planning cadence","reconcile weekly detail with monthly workforce decisions","Create a 12-week capacity view with risks and actions."],
 "Workforce Supply Projection":["opening headcount, attrition, hiring, transfers, leave, and productivity ramp","build a transparent workforce supply waterfall","Project six months of supply from workforce movements."],
 "Hiring, Training, and Ramp Planning":["recruitment lead time, class size, training capacity, nesting, and proficiency","backsolve hiring dates from the date capacity is required","Design a hiring and ramp plan for a future staffing gap."],
 "Long-Range Capacity Strategy":["multi-year demand, location, sourcing, automation, and capability strategy","connect workforce choices with strategic scenarios","Build three long-range capacity options for leadership review."],
 "Financial Workforce Scenarios":["labor cost, overtime, outsourcing, hiring, productivity, and service tradeoffs","compare scenarios using operational and financial measures","Evaluate build, buy, and overtime options for a demand increase."],
 "Capacity Governance":["assumption ownership, decision calendars, version control, and action tracking","establish a repeatable capacity-planning operating rhythm","Design a governance calendar with owners and approval gates."],
 "Essential WFM Metrics":["service, demand, productivity, staffing, schedule, and employee measures","match each metric to the decision it should support","Create a one-page metric map for a WFM team."],
 "Understanding Variance":["plan-versus-actual variance, materiality, timing, and driver decomposition","move from a variance symptom to a testable explanation","Analyze a service miss using demand, AHT, staffing, and adherence."],
 "Metric Definitions and Data Quality":["metric formulas, grain, filters, sources, ownership, and reconciliation","write definitions that produce repeatable results","Build a metric dictionary entry and data-quality checklist."],
 "Forecast, Staffing, and Schedule Analysis":["linked analysis across demand, requirement, schedule, and actual staffing","identify which planning layer created the operational gap","Trace a service issue through forecast, capacity, and schedule data."],
 "Building a WFM Dashboard":["decision-focused layout, hierarchy, thresholds, trends, and drill paths","select visuals that reveal action rather than add clutter","Design a dashboard wireframe for a weekly performance review."],
 "WFM Root-Cause Analysis":["problem framing, evidence trees, segmentation, hypothesis testing, and validation","distinguish correlation from a supported operational cause","Complete a root-cause analysis for repeated Monday service misses."],
 "Executive WFM Storytelling":["business context, insight, impact, options, recommendation, and ask","translate technical WFM findings into an executive narrative","Create a five-slide story for a material capacity risk."],
 "Performance Governance":["performance cadence, metric ownership, thresholds, decisions, and escalation","turn reporting meetings into accountable decision forums","Design a monthly WFM performance-governance agenda."],
 "Benefits and Action Tracking":["baseline, target, owner, milestone, benefit logic, and sustainability","measure whether an action delivered the intended outcome","Build a benefits tracker for a schedule-optimization initiative."],
 "The Employee Schedule Experience":["visibility, predictability, usability, communication, and employee control","map the employee journey from schedule publication to change","Assess a schedule journey and identify friction points."],
 "Time-Off, Availability, and Preferences":["availability rules, leave requests, preferences, approvals, and coverage","distinguish availability constraints from employee preferences","Design a transparent request and approval workflow."],
 "Workforce Self-Service Fundamentals":["employee transactions, eligibility, guardrails, approvals, and auditability","identify which schedule actions can be safely self-served","Define controls for a basic workforce self-service program."],
 "Shift Swaps and Self-Service":["swap eligibility, skill matching, coverage protection, approvals, and audit trail","evaluate a swap without weakening service or compliance","Review five swap requests and explain each decision."],
 "Schedule Preferences and Bidding":["preference collection, ranking, bidding rules, seniority, points, and transparency","design an understandable and auditable allocation method","Run a small schedule bid and document unresolved conflicts."],
 "Fairness and Communication":["procedural fairness, consistency, accessibility, explanation, and appeal","communicate unfavorable schedule decisions with clear standards","Draft a communication and appeal process for leave allocation."],
 "Strategic Workforce Flexibility":["flex pools, part-time models, annualized hours, remote work, and voluntary programs","select flexibility options based on demand shape and workforce needs","Create a flexibility portfolio for seasonal demand."],
 "Engagement Program Governance":["policy ownership, controls, privacy, eligibility, exceptions, and monitoring","govern employee flexibility without unnecessary friction","Design governance for an enterprise shift-swap program."],
 "Employee Experience Measurement":["adoption, access, fulfillment, fairness, stability, service, and qualitative feedback","combine employee and operational evidence to judge program value","Build a balanced scorecard for schedule self-service."]
};
function Lesson({mod,lesson,level,progress,setProgress,onPrevious,onNext,hasPrevious,hasNext}){
 const [focus,action,exercise]=lessonFocus[lesson.title]||["the lesson’s central WFM method","apply the method to a workforce decision","Complete a practical workforce exercise."];
 const lessonDetailSources={
  realtime:realtimeLessonDetails,
  scheduling:schedulingLessonDetails,
  forecasting:forecastingLessonDetails,
  capacity:capacityLessonDetails,
  analytics:analyticsLessonDetails
 };
 const lessonRefinementSources={
  scheduling:schedulingRefinements,
  forecasting:forecastingRefinements,
  capacity:capacityRefinements,
  analytics:analyticsRefinements
 };
 const detail=lessonDetailSources[mod.id]?.[lesson.title]||null;
 const levelLabel=levels.find(x=>x.id===level)?.label||level;
 const depth=level==="beginner"?"Build a clear foundation and use the method with guided examples.":level==="intermediate"?"Apply the method to connected operational data and explain tradeoffs.":"Lead complex decisions, establish controls, and communicate enterprise impact.";
 const refinement=lessonRefinementSources[mod.id]?.[lesson.title]||null;
 const objectives=[`Explain ${focus}.`,`${action.charAt(0).toUpperCase()+action.slice(1)}.`,refinement?.objective||`Document the result, assumptions, risk, and recommended next action.`];
 const [answers,setAnswers]=useState({});
 const [showAnswers,setShowAnswers]=useState(false);
 const [showModelAnswer,setShowModelAnswer]=useState(false);


 if(detail){
  return <article className="mx-auto max-w-5xl overflow-hidden rounded-3xl border border-slate-200 bg-[#f7f9f9] shadow-sm">
   <header className="border-b bg-gradient-to-br from-white via-violet-50/40 to-slate-50 p-7 lg:p-10">
    <div className="flex flex-wrap items-center justify-between gap-3"><p className="text-[10px] font-black uppercase tracking-[.16em]" style={{color:mod.color}}>{mod.label} · {levelLabel}</p><div className="flex gap-2"><span className="rounded-full border bg-white px-3 py-1 text-[10px] font-black">Lesson</span><span className="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-black">{lesson.duration}</span></div></div>
    <h2 className="mt-4 font-serif text-3xl font-black lg:text-5xl">{lesson.title}</h2>
    <p className="mt-4 max-w-3xl text-sm leading-7 text-slate-600">{detail.overview}</p>
    <div className="mt-5 rounded-xl border-l-4 bg-white p-4" style={{borderColor:mod.color}}><b className="text-xs uppercase tracking-wide">Level expectation</b><p className="mt-2 text-sm leading-6">{depth}</p></div>
   </header>


   <div className="space-y-8 p-7 lg:p-10">
    <section><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>01 · Learning objectives</p><h3 className="mt-2 font-serif text-2xl font-black">What you will be able to do</h3><div className="mt-4 grid gap-3">{objectives.map(x=><p key={x} className="flex gap-3 rounded-xl border bg-white p-4 text-sm leading-6"><CheckCircle2 size={17} className="shrink-0" style={{color:mod.color}}/>{x}</p>)}</div></section>


    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>02 · Key terminology</p><h3 className="mt-2 font-serif text-2xl font-black">Build the operating vocabulary</h3><div className="mt-5 grid gap-3 md:grid-cols-2">{detail.terms.map(([term,definition])=><div key={term} className="rounded-2xl border bg-white p-5"><h4 className="font-black">{term}</h4><p className="mt-2 text-sm leading-6 text-slate-600">{definition}</p></div>)}</div></section>


    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>03 · Practitioner method</p><h3 className="mt-2 font-serif text-2xl font-black">A repeatable decision process</h3><div className="mt-5 space-y-3">{detail.method.map((x,i)=><div key={x} className="flex items-center gap-4 rounded-xl border bg-white p-4"><span className="grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-black text-white" style={{background:mod.color}}>{i+1}</span><p className="text-sm font-semibold leading-6">{x}</p></div>)}</div></section>


    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>04 · Worked example</p><h3 className="mt-2 font-serif text-2xl font-black">{detail.example.title}</h3><div className="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="rounded-2xl bg-slate-900 p-5 text-white"><p className="text-[10px] font-black uppercase tracking-wide text-violet-300">Operating facts</p>{detail.example.facts.map(x=><p key={x} className="mt-3 border-b border-white/10 pb-3 text-sm last:border-0">{x}</p>)}</div><div className="space-y-4"><div className="rounded-2xl border bg-white p-5"><h4 className="font-black">Analysis</h4><p className="mt-2 text-sm leading-7 text-slate-600">{detail.example.analysis}</p></div><div className="rounded-2xl border-l-4 bg-violet-50 p-5" style={{borderColor:mod.color}}><h4 className="font-black">Recommended decision</h4><p className="mt-2 text-sm leading-7">{detail.example.decision}</p></div></div></div></section>


    {refinement&&<section className="border-t pt-8"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>05 · Formula and calculation</p><h3 className="mt-2 font-serif text-2xl font-black">Make the analytical logic visible</h3><div className="mt-5 rounded-2xl bg-slate-900 p-5 text-white"><p className="text-[10px] font-black uppercase tracking-wide text-emerald-300">{refinement.label||"Formula"}</p><p className="mt-3 font-mono text-sm leading-7">{refinement.formula}</p></div><div className="mt-3 grid gap-3 md:grid-cols-2">{refinement.calculation.map((x,i)=><div key={x} className="flex gap-3 rounded-xl border bg-white p-4"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-black text-white" style={{background:mod.color}}>{i+1}</span><p className="text-sm leading-6">{x}</p></div>)}</div></section>}
    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase text-rose-600">{refinement?"06":"05"} · Common mistakes</p><h3 className="mt-2 font-serif text-2xl font-black">What to avoid</h3><div className="mt-4 grid gap-3 md:grid-cols-2">{detail.mistakes.map(x=><p key={x} className="rounded-xl border border-rose-100 bg-rose-50 p-4 text-sm leading-6">{x}</p>)}</div></section>


    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase text-amber-700">{refinement?"07":"06"} · Applied exercise</p><div className="mt-3 rounded-2xl bg-amber-50 p-6"><h3 className="font-serif text-2xl font-black">Scenario task</h3><p className="mt-3 text-sm leading-7">{exercise}</p>{refinement&&<div className="mt-5 rounded-xl border border-amber-200 bg-white p-5"><h4 className="font-black">Exercise dataset</h4><div className="mt-3 grid gap-2">{refinement.dataset.map(x=><p key={x} className="flex gap-3 text-sm leading-6"><span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500"/>{x}</p>)}</div></div>}<p className="mt-4 text-sm leading-7"><b>Required output:</b> assumptions, calculation or analysis, finding, recommended action, owner, timing, and success measure.</p>{refinement&&<div className="mt-5"><button onClick={()=>setShowModelAnswer(v=>!v)} className="rounded-xl border border-amber-300 bg-white px-5 py-3 text-xs font-black text-amber-800">{showModelAnswer?"Hide model answer":"Show model answer"}</button>{showModelAnswer&&<div className="mt-3 rounded-xl border-l-4 bg-emerald-50 p-5" style={{borderColor:mod.color}}><h4 className="font-black">Model answer</h4><p className="mt-2 text-sm leading-7">{refinement.modelAnswer}</p></div>}</div>}</div></section>


    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase text-emerald-700">{refinement?"08":"07"} · Knowledge check</p><h3 className="mt-2 font-serif text-2xl font-black">Test your understanding</h3><p className="mt-2 text-sm leading-6 text-slate-600">Select one answer for each question, then use Check answers to review the correct responses.</p><div className="mt-5 space-y-5">{detail.quiz.map(([question,options,correct],qi)=><div key={question} className="rounded-2xl border bg-white p-5"><h4 className="font-black">{qi+1}. {question}</h4><div className="mt-3 grid gap-2">{options.map((option,oi)=>{const chosen=answers[qi]===oi;const resultClass=showAnswers?(oi===correct?"border-emerald-400 bg-emerald-50":chosen?"border-rose-300 bg-rose-50":"border-slate-200"):chosen?"border-violet-400 bg-violet-50":"border-slate-200";return <button key={option} onClick={()=>setAnswers(a=>({...a,[qi]:oi}))} className={`rounded-xl border p-3 text-left text-sm ${resultClass}`}>{option}</button>})}</div>{showAnswers&&<p className={`mt-3 text-xs font-black ${answers[qi]===correct?"text-emerald-700":"text-rose-700"}`}>{answers[qi]===correct?"Correct":"Review the highlighted correct answer"}</p>}</div>)}</div><div className="mt-4 flex flex-wrap gap-3"><button onClick={()=>setShowAnswers(v=>!v)} className="rounded-xl bg-slate-900 px-5 py-3 text-xs font-black text-white">{showAnswers?"Hide answers":"Check answers"}</button>{showAnswers&&<button onClick={()=>{setAnswers({});setShowAnswers(false)}} className="rounded-xl border border-slate-300 bg-white px-5 py-3 text-xs font-black text-slate-700">Reset quiz</button>}</div></section>

    <section className="border-t pt-8"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>{refinement?"09":"08"} · Key takeaways</p><div className="mt-4 grid gap-3 md:grid-cols-3">{detail.takeaways.map((x,i)=><div key={x} className="rounded-2xl border bg-white p-5"><span className="text-xs font-black" style={{color:mod.color}}>0{i+1}</span><p className="mt-2 text-sm font-semibold leading-6">{x}</p></div>)}</div></section>


    <div className="border-t pt-8"><div className="flex flex-wrap items-center justify-between gap-3"><button onClick={onPrevious} disabled={!hasPrevious} className={`rounded-xl border px-5 py-3 text-xs font-black ${hasPrevious?"border-slate-300 bg-white text-slate-700 hover:bg-slate-50":"cursor-not-allowed border-slate-200 bg-slate-100 text-slate-400"}`}>Previous lesson</button><button onClick={()=>setProgress(p=>({...p,[lesson.id]:!p[lesson.id]}))} className="rounded-xl bg-emerald-600 px-5 py-3 text-xs font-black text-white">{progress[lesson.id]?"Lesson completed · Undo":"Mark lesson complete"}</button><button onClick={onNext} disabled={!hasNext} className={`rounded-xl px-5 py-3 text-xs font-black text-white ${hasNext?"bg-violet-600 hover:bg-violet-700":"cursor-not-allowed bg-slate-300"}`}>Next lesson <ArrowRight size={14} className="ml-1 inline"/></button></div></div>
   </div>
  </article>
 }


 return <article className="mx-auto max-w-5xl overflow-hidden rounded-3xl border bg-white shadow-sm"><header className="border-b bg-gradient-to-br from-white to-slate-50 p-7 lg:p-10"><div className="flex flex-wrap justify-between gap-3"><p className="text-[10px] font-black uppercase tracking-[.16em]" style={{color:mod.color}}>{mod.label} · {levelLabel}</p><span className="rounded-full bg-slate-100 px-3 py-1 text-[10px] font-black">{lesson.duration}</span></div><h2 className="mt-3 text-3xl font-black lg:text-4xl">{lesson.title}</h2><p className="mt-4 max-w-3xl text-sm leading-7 text-slate-600">This lesson develops practical capability in {focus}. {depth}</p></header><div className="space-y-7 p-7 lg:p-10"><section><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>Learning objectives</p><div className="mt-4 grid gap-3">{objectives.map(x=><p key={x} className="flex gap-3 rounded-xl border bg-slate-50 p-4 text-sm leading-6"><CheckCircle2 size={17} className="shrink-0" style={{color:mod.color}}/>{x}</p>)}</div></section><section className="border-t pt-7"><p className="text-[10px] font-black uppercase" style={{color:mod.color}}>Core lesson</p><h3 className="mt-2 text-xl font-black">What this topic means in practice</h3><p className="mt-3 text-sm leading-7 text-slate-600">The practitioner must understand {focus}, validate the information behind the decision, and connect demand, workforce supply, timing, constraints, and business impact before recommending action.</p></section><section className="border-t pt-7"><p className="text-[10px] font-black uppercase text-amber-700">Applied exercise</p><div className="mt-3 rounded-2xl bg-amber-50 p-5"><h3 className="font-black">Scenario task</h3><p className="mt-2 text-sm leading-7">{exercise}</p></div></section><button onClick={()=>setProgress(p=>({...p,[lesson.id]:!p[lesson.id]}))} className="rounded-xl bg-emerald-600 px-5 py-3 text-xs font-black text-white">{progress[lesson.id]?"Lesson completed · Undo":"Mark lesson complete"}</button></div></article>
}
function Learning({initialModule,progress,setProgress}){
 const[moduleId,setModuleId]=useState(initialModule),[level,setLevel]=useState("beginner"),[selected,setSelected]=useState(null);
 const mod=modules.find(x=>x.id===moduleId);
 const durationByLevel={beginner:[25,30,35],intermediate:[35,40,45],professional:[45,50,55]};
 const lessons=lessonTitles[moduleId][level].map((title,i)=>({id:`${moduleId}-${level}-${i+1}`,title,duration:`${durationByLevel[level][i]} min`}));
 const selectedIndex=selected?lessons.findIndex(x=>x.id===selected.id):-1;
 const chooseLesson=index=>{if(index>=0&&index<lessons.length){setSelected(lessons[index]);window.scrollTo({top:0,behavior:"smooth"})}};
 return <>
  <p className="text-[10px] font-black uppercase text-violet-600">Academy</p><h1 className="mt-1 text-3xl font-black">WFM learning paths</h1><p className="mt-2 text-sm text-slate-500">Six disciplines, three career levels, and 54 practical lessons.</p>
  <div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{modules.map(x=>{const I=x.icon;return <button key={x.id} onClick={()=>{setModuleId(x.id);setSelected(null)}} className={`rounded-2xl border p-4 text-left ${moduleId===x.id?"border-violet-300 bg-violet-50 ring-2 ring-violet-100":"bg-white"}`}><I size={20} style={{color:x.color}}/><h2 className="mt-2 font-black">{x.label}</h2><p className="mt-1 text-xs leading-5 text-slate-500">{x.desc}</p></button>})}</div>
  <div className="mt-4 flex flex-wrap gap-3"><select value={level} onChange={e=>{setLevel(e.target.value);setSelected(null)}} className="rounded-xl border bg-white px-4 py-3 text-xs font-bold">{levels.map(x=><option key={x.id} value={x.id}>{x.label}</option>)}</select><select value={selected?.id||"orientation"} onChange={e=>setSelected(e.target.value==="orientation"?null:lessons.find(x=>x.id===e.target.value))} className="min-w-72 rounded-xl border bg-white px-4 py-3 text-xs font-bold"><option value="orientation">Module overview</option>{lessons.map((x,i)=><option key={x.id} value={x.id}>Lesson {i+1}: {x.title} ({x.duration}){progress[x.id]?" - Completed":""}</option>)}</select></div>
  <div className="mt-4">{selected?<Lesson key={selected.id} mod={mod} lesson={selected} level={level} progress={progress} setProgress={setProgress} hasPrevious={selectedIndex>0} hasNext={selectedIndex<lessons.length-1} onPrevious={()=>chooseLesson(selectedIndex-1)} onNext={()=>chooseLesson(selectedIndex+1)}/>:<Orientation mod={mod} level={level} onBegin={()=>chooseLesson(0)}/>}</div>
 </>
}
function Tools(){const[v,setV]=useState({volume:4940,aht:798,hours:8,shrinkage:30});const r=useMemo(()=>{const workload=v.volume*v.aht/3600,base=workload/Math.max(1,v.hours),gross=base/Math.max(.01,1-v.shrinkage/100);return{workload,base,gross}},[v]);return <><h1 className="text-3xl font-black">WFM Tools</h1><Card className="mt-6"><div className="grid gap-4 sm:grid-cols-2">{Object.entries(v).map(([k,val])=><label key={k}><span className="text-[10px] font-black uppercase">{k}</span><input type="number" value={val} onChange={e=>setV(p=>({...p,[k]:Number(e.target.value)}))} className="mt-1 h-12 w-full rounded-xl border bg-slate-50 px-4"/></label>)}</div><div className="mt-6 grid gap-3 sm:grid-cols-3">{[["Workload",`${r.workload.toFixed(2)} hrs`],["Baseline FTE",r.base.toFixed(2)],["Gross FTE",r.gross.toFixed(2)]].map(([k,x])=><div key={k} className="rounded-2xl bg-slate-50 p-5"><b className="text-xs">{k}</b><div className="text-2xl font-black">{x}</div></div>)}</div></Card></>}


export default function App(){const[page,setPage]=useState("overview"),[mobile,setMobile]=useState(false),[selectedModule,setSelectedModule]=useState("realtime"),[progress,setProgress]=useState(()=>{try{return JSON.parse(localStorage.getItem("wfm-progress"))||{}}catch{return{}}});useEffect(()=>{try{localStorage.setItem("wfm-progress",JSON.stringify(progress))}catch{}},[progress]);const complete=Object.values(progress).filter(Boolean).length;const go=id=>{setPage(id);setMobile(false)};const Nav=()=> <><Logo/><nav className="mt-9 space-y-2">{nav.map(x=>{const I=x.icon;return <button key={x.id} onClick={()=>go(x.id)} className={`flex w-full items-center gap-3 rounded-xl px-4 py-3 text-xs font-bold ${page===x.id?"bg-violet-100 text-violet-700":"text-slate-500"}`}><I size={17}/>{x.label}</button>})}</nav><div className="absolute bottom-5 left-4 right-4 rounded-3xl bg-[#24213f] p-4 text-white"><b className="text-xs">Your WFM journey</b><p className="mt-2 text-[10px]">{complete} of {TOTAL_LESSONS} completed</p></div></>;return <div className="min-h-screen bg-[#f6f7fb] text-slate-800"><aside className="fixed inset-y-0 left-0 hidden w-64 border-r bg-white p-5 lg:block"><Nav/></aside>{mobile&&<div className="fixed inset-0 z-50 bg-slate-950/40 lg:hidden"><aside className="relative h-full w-72 bg-white p-5"><button onClick={()=>setMobile(false)} className="absolute right-4 top-4"><X/></button><Nav/></aside></div>}<main className="lg:pl-64"><header className="sticky top-0 z-30 flex h-16 items-center border-b bg-white/90 px-5"><button onClick={()=>setMobile(true)} className="mr-3 lg:hidden"><Menu/></button><div className="ml-auto rounded-xl bg-emerald-50 px-3 py-2 text-xs font-black text-emerald-700">{complete}/{TOTAL_LESSONS} lessons</div></header><div className={`mx-auto w-full p-5 lg:p-8 ${page==="learn"?"max-w-none":"max-w-7xl"}`}>{page==="overview"&&<><section className="rounded-[32px] bg-gradient-to-br from-[#211f3b] to-[#5144be] p-8 text-white"><Sparkles size={14}/><h1 className="mt-4 text-4xl font-black sm:text-5xl">Learn. Calculate. Decide.<br/><span className="text-violet-300">Master WFM.</span></h1><p className="mt-4 text-sm text-slate-300">Build practical expertise across six connected disciplines.</p><div className="mt-7 flex gap-3"><button onClick={()=>go("learn")} className="rounded-xl bg-violet-500 px-5 py-3 text-xs font-black"><Play size={14} className="mr-2 inline"/>Start learning</button><button onClick={()=>go("tools")} className="rounded-xl border px-5 py-3 text-xs">Open tools</button></div></section><div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{modules.map(x=>{const I=x.icon;return <button key={x.id} onClick={()=>{setSelectedModule(x.id);go("learn")}} className="rounded-3xl border bg-white p-5 text-left"><I style={{color:x.color}}/><h2 className="mt-3 font-black">{x.label}</h2><p className="text-xs text-slate-500">{x.desc}</p></button>})}</div></>}{page==="learn"&&<Learning key={selectedModule} initialModule={selectedModule} progress={progress} setProgress={setProgress}/>} {page==="tools"&&<Tools/>}{page==="resources"&&<div><h1 className="text-3xl font-black">Resources</h1><div className="mt-6 grid gap-4 md:grid-cols-3">{["WFM Formula Guide","Planning Templates","Metric Dictionary"].map(x=><Card key={x}><BookOpen className="text-violet-600"/><h2 className="mt-4 font-black">{x}</h2></Card>)}</div></div>}</div></main></div>}
